\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 u. (127\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 \endash 129\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 ) Maria Magdalena (22.7.). \plain \f1\i\lang1033\fs22 >Von sannt Maria Magdalena.< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O nempt war, alle menschen, den spiegel hailsamer buos Maria Magdalena, wie gar alles ye hoffertiglich ... }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 (128}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\super\lang1033\fs28\chcbpat17 v}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 )}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17  geruch auch mich armen sunder}}\plain \f1\i\lang1033\fs22  genade warhaftige bus zu erwerben ...  \plain \f1\lang1033\fs22 Parallel\u252 \'fcberlieferung: {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 GW 12995}}\plain \f1\lang1033\fs22 , Bl. u6\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 \endash w2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 ; Trier, Stadtbibl., {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Hs. 819/10 8\u176 \'b0}}\plain \f1\lang1033\fs22 , Bl. 145\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 \endash 148\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 ; au\u223 \'dferdem Augsburg, UB, {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Cod. I.3.8\u176 \'b0 1}}\plain \f1\lang1033\fs22 , Bl. 113\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 \endash 117\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  (\plain \f1\scaps\lang1033\fs22 Schneider\plain \f1\lang1033\fs22  1988, S. 109); ebd., {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Cod. III.1.8\u176 \'b0 38}}\plain \f1\lang1033\fs22 , Bl. 133\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 \endash 136\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22  (ebd., S. 577); M\u252 \'fcnchen, BSB, {\field{\*\fldinst HYPERLINK "hida://5007[3].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Cgm 121}}\plain \f1\lang1033\fs22 , Bl. 294\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 \endash 296\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 ; ebd., {\field{\*\fldinst HYPERLINK "hida://5007[4].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Cgm 833}}\plain \f1\lang1033\fs22 , Bl. 129\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 \endash 131\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  (\plain \f1\scaps\lang1033\fs22 Schneider\plain \f1\lang1033\fs22  1984, S. 535); ebd., {\field{\*\fldinst HYPERLINK "hida://5007[5].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Cgm 4685}}\plain \f1\lang1033\fs22 , Bl. 140\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 \endash 144\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22  (\plain \f1\scaps\lang1033\fs22 Schneider\plain \f1\lang1033\fs22  1996, S. 324); ebd., {\field{\*\fldinst HYPERLINK "hida://5007[6].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Cgm 5942}}\plain \f1\lang1033\fs22 , Bl. 197\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 \endash 199\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  (\plain \f1\scaps\lang1033\fs22 Wunderle\plain \f1\lang1033\fs22  2018, S. 390).}

