\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 130\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 \endash 132\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs22\chcbpat17 Mariengebet}}\plain \f1\caps\lang1033\fs22  (Maria mit Edelsteinen verglichen).\plain \f1\b\lang1033\fs22   \plain \f1\i\lang1033\fs22 >Ein schon gebet von Maria der himelkunigin wolgezierte mit edelm gestain.< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Maria, du gewaltige k\u252 \'fcnigin der himel, du hailige keiserin der enngel, du widerbringerin der sonder ... zu dir fliehent die armen}}\plain \f1\i\lang1033\fs22  ... \plain \f1\lang1033\fs22 (130\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 )\plain \f1\i\lang1033\fs22  erhore mich vnnd merck mein gebet, mein ruffen, mein schreyen ...\~\endash \~... reich mir hilf in meinem leben, gedultigkeit, weishait, lauterkeit an leib vnnd an sele. Amen.  \plain \f1\lang1033\fs22 Sehr h\u228 \'e4ufig \u252 \'fcberliefertes Gebet. \plain \f1\scaps\lang1033\fs22 Haimerl\plain \f1\lang1033\fs22  1952, S. 154, Anm. 953. Seeleng\u228 \'e4rtlein W, S. 421\endash 425. \u220 \'dcberlieferungsnachweise u.\~a. bei \plain \f1\scaps\lang1033\fs22 Schneider\plain \f1\lang1033\fs22  1984, S. 531 und S. 661; \plain \f1\scaps\lang1033\fs22 Schneider\plain \f1\lang1033\fs22  1996, S. 408; \plain \f1\scaps\lang1033\fs22 Vizkelety\plain \f1\lang1033\fs22  1969\endash 1973, Bd. 1, S. 62. Weitere \u220 \'dcberlieferung u.\~a.: Augsburg, UB, {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Cod. III. 1. 8\u176 \'b0 3}}\plain \f1\lang1033\fs22 , Bl. 129\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 \endash 130\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 ; ebd., {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Cod. III. 1. oct. 6}}\plain \f1\lang1033\fs22 , Bl. 86\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 \endash 89\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 ; Dresden, SLUB, {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Mscr.Dresd.M.180}}\plain \f1\lang1033\fs22 , Bl. 29\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs22 ; Leipzig, UB, {\field{\*\fldinst HYPERLINK "hida://5007[3].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Ms 1660}}\plain \f1\lang1033\fs22 , Bl. 7\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 ; ebd., {\field{\*\fldinst HYPERLINK "hida://5007[4].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Rep. II 166}}\plain \f1\lang1033\fs22 , Bl. 73\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 ; New Haven (Connecticut), Yale University. Beinecke Rare Book and Manuscript Library, {\field{\*\fldinst HYPERLINK "hida://5007[5].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 MS 28}}\plain \f1\lang1033\fs22 , Bl. 58\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 \endash 59\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  (s.\~o.).}

