\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 132\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 \endash 134\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs22\chcbpat17 Gebet zur hl. Katharina}}\plain \f1\caps\lang1033\fs22 .\plain \f1\b\lang1033\fs22   \plain \f1\i\lang1033\fs22 >Von der hailigen junckfrauen sant Katherina.< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O wie loblich aus k\u252 \'fcniglichem stammen entsprungen vnnd also f\u252 \'fcrsichtiglichen aufgezogen pist du, o hailige junckfrau sant Katherina}}\plain \f1\i\lang1033\fs22  ... \plain \f1\lang1033\fs22 (134\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 )\plain \f1\i\lang1033\fs22  also ruf ich auch zu dir mit herczlicher diem\u252 \'fctigkait ...\~\endash \~... do mit ich deiner heiligen hilff seliglich werde genossen enpfinden. Amen.  \plain \f1\lang1033\fs22 Parallel\u252 \'fcberlieferung: {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 GW 12995}}\plain \f1\lang1033\fs22 , Bl. A4\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 \endash A8\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 ; Trier, Stadtbibl., {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Hs. 819/10 8\u176 \'b0}}\plain \f1\lang1033\fs22 , Bl. 180\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 \endash 181\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22  (s.\~o. zu Bl. 87\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22  und 107\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 ); au\u223 \'dferdem Augsburg, UB, {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Cod. I.3.8\u176 \'b0 1}}\plain \f1\lang1033\fs22 , Bl. 105\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 \endash 109\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  (\plain \f1\scaps\lang1033\fs22 Schneider\plain \f1\lang1033\fs22  1988, S. 109); ebd., {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Cod. III.1.8\u176 \'b0 38}}\plain \f1\lang1033\fs22 , Bl. 148\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 \endash 154\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  (ebd., S. 577); M\u252 \'fcnchen, BSB, {\field{\*\fldinst HYPERLINK "hida://5007[3].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Cgm 121}}\plain \f1\lang1033\fs22 , Bl. 296\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 \endash 300\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 ; ebd., {\field{\*\fldinst HYPERLINK "hida://5007[4].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Cgm 833}}\plain \f1\lang1033\fs22 , Bl. 131\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 \endash 133\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  (\plain \f1\scaps\lang1033\fs22 Schneider\plain \f1\lang1033\fs22  1984, S. 535); ebd., {\field{\*\fldinst HYPERLINK "hida://5007[5].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Cgm 4640}}\plain \f1\lang1033\fs22 , Bl. 151\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 \endash 160\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  (\plain \f1\scaps\lang1033\fs22 Schneider\plain \f1\lang1033\fs22  1996, S. 276); ebd., {\field{\*\fldinst HYPERLINK "hida://5007[6].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Cgm 5942}}\plain \f1\lang1033\fs22 , Bl. 199\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 \endash 202\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  (\plain \f1\scaps\lang1033\fs22 Wunderle\plain \f1\lang1033\fs22  2018, S. 390); Salzburg, Stiftsbibl. St. Peter, {\field{\*\fldinst HYPERLINK "hida://5007[7].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 b II 30}}\plain \f1\lang1033\fs22 , Bl. 154\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22  (\plain \f1\scaps\lang1033\fs22 Hayer\plain \f1\lang1033\fs22  1982, S. 475, Nr. 453).}

