\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 33\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 \u8722 -36\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\caps\lang1033\fs22\chcbpat17 Sechs Dinge der Kontemplation}}\plain \f1\lang1033\fs22 .  \plain \f1\i\lang1033\fs22 >Von contemplieren.<\plain \f1\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Swer gerne contemplierin wil, der bedarf wol .vi. sehis dinge}}\plain \f1\i\lang1033\fs22 , in den er sich v\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs22 be, dc er gevalle gotiz o\plain \f1\i\super\lang1033\fs24 v\plain \f1\i\lang1033\fs22 gin ... Daz erste ist, dc sich der mensch in manic valten gu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs22 ten werkin v\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs22 be ... \u8722 - ... in durnotim vnd ganzim gelo\plain \f1\i\super\lang1033\fs24 v\plain \f1\i\lang1033\fs22 bin belibt man st\u230 \'e6t an got.  \plain \f1\lang1033\fs22 Parallel\u252 \'fcberlieferung: Augsburg, UB, {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 III.1.4\u176 \'b0 9}}\plain \f1\lang1033\fs22 , Bl. 17\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 \u8722 -18\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 ; M\u252 \'fcnchen, BSB, {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Cgm 100}}\plain \f1\lang1033\fs22 , Bl. 182\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22  (nur Anfang); ebd., {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Cgm 4414}}\plain \f1\lang1033\fs22 , Bl. 289\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 \u8722 -291\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 ; ebd., {\field{\*\fldinst HYPERLINK "hida://5007[3].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Clm 14126}}\plain \f1\lang1033\fs22 , Bl. 308\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 . Vgl. \plain \f1\scaps\lang1033\fs22 Schneider\plain \f1\lang1033\fs22  1988, S. 273; \plain \f1\scaps\lang1033\fs22 Schneider\plain \f1\lang1033\fs22  1996, S. 115. Zu den Hss. vgl. unten Bl. 84\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 . Auch {\field{\*\fldinst HYPERLINK "hida://5007[4].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 St. Georgen 38}}\plain \f1\lang1033\fs22 , Bl. 19\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 \u8722 -23\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 .}

