\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 39\plain \f1\super\lang1033\fs24 r\u8722 -v\plain \f1\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\caps\lang1033\fs22\chcbpat17 \u220 \'dcber die vier Kardinaltugenden}}\plain \f1\caps\lang1033\fs22 .\plain \f1\caps\lang1033\fs22   {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Ez sint .iiii. tuginde, die haizint mu}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs28\chcbpat17 o}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 ter aller tuginde}}\plain \f1\i\lang1033\fs22 . Diu .i. dc ist gelo\plain \f1\i\super\lang1033\fs24 v\plain \f1\i\lang1033\fs22 be ...\plain \f1\lang1033\fs22  [39\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 ] \plain \f1\i\lang1033\fs22 Diu mu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs22 ter tv\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs22 t ir kinden .iiii. dinc. Si gebirt ez ... \u8722 - ... vnd leret si diu beschaidenhait.\plain \f1\lang1033\fs22   Parallel\u252 \'fcberlieferung: M\u252 \'fcnchen, BSB, {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Cgm 531}}\plain \f1\lang1033\fs22 , Bl. 111\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs22 ; ebd., {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Cgm 5141}}\plain \f1\lang1033\fs22 , Bl. 138\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 \u8722 -139\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 ; Z\u252 \'fcrich, Stadtbibl., {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 C 76/290}}\plain \f1\lang1033\fs22 , Bl. 146\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs22 . Zur \u220 \'dcberlieferung vgl. \plain \f1