\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 40\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\caps\lang1033\fs22\chcbpat17 Drei Zeichen der Liebe}}\plain \f1\caps\lang1033\fs22 .\plain \f1\caps\lang1033\fs22  \plain \f1\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Ez sint .iii . zaichin der minne. Dc .i., dc der mensch nicht rede wan von gote}}\plain \f1\i\lang1033\fs22  ...\plain \f1\lang1033\fs22   Abweichend: Vier Zeichen der Liebe in: Gotha, FB, {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Chart. B 237}}\plain \f1\lang1033\fs22 , Bl. 12\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 ; Heidelberg, UB, {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Cod. pal. germ. 28}}\plain \f1\lang1033\fs22 , Bl. 91\plain \f1\super\lang1033\fs24 ra\u8722 -rb\plain \f1\lang1033\fs22 .}

