\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 42\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 \u8722 -46\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs22\chcbpat17 Tugendlehre f\u252 \'fcr Nonnen}}\plain \f1\caps\lang1033\fs22  (Zisterzienserinnen).\plain \f1\lang1033\fs22   {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Diz ist ain anevanc vnd ain ler ains armin menschin, dc nicht mac komin}}\plain \f1\i\lang1033\fs22  zv\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs22  der hohi der tuginde vnd zv\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs22  der gabe der gnade vnd zv\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs22  dem liehte der sele, wie du dich vzwendic vnd inwendic haltin solt. Du sol\plain \f1\lang1033\fs22 [t] \plain \f1\i\lang1033\fs22 zu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs22 htic sin vzwendic sin \plain \f1\lang1033\fs22 [!]\plain \f1\i\lang1033\fs22  an dinen siten vnd solt dich alle zit  in hu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs22 te han, wie du wol gevalles dem himilschun bru\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs22 tegv\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs22 m, der diner tuginde alle\plain \f1\lang1033\fs22  [43\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 ] \plain \f1\i\lang1033\fs22 zit begerende ist durch din hail ...\plain \f1\lang1033\fs22  (44\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 :) \plain \f1\i\lang1033\fs22 Du solt dich nit annemin sundeliches lebinnes, also dc nieman von dir ze redinne habe, weder von diner gv\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs22 ti noch von diner v\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs22 bli. Vnd den lu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs22 ten spricht \plain \f1\b\i\lang1033\fs22 vnser vatir sant {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\b\i\lang1033\fs22\chcbpat17 Bernhart}}\plain \f1\i\lang1033\fs22 , dc die di bestin \plain \f1\b\i\lang1033\fs22 in den clostirn\plain \f1\i\lang1033\fs22  sint ... \plain \f1\i\lang1033\fs22\cf1 \u8722 - \plain \f1\i\lang1033\fs22 ... Vor allen dingin so man ich dich, dc du dich hu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs22 tist vor nahrede vnd vor lieginne vnd vor spotinne. Wis mezic an diner rede vnd hu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs22 te dich vor herten vnd zornlichen worten.  \plain \f1\lang1033\fs22 Textproben: \plain \f1\scaps\lang1033\fs22 M\plain \f1\scaps\lang1033\fs22 one\plain \f1\lang1033\fs22  1835, Sp. 369, Nr. 28\u8722 -30 (Bl. 45\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 \u8722 -46\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 ).}

