\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 d. (11\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 18\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 >Nu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 n von den zaichen der folku\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 mnen go\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 tlichen gena\plain \f1\i\super\lang1033\fs24 v\plain \f1\i\lang1033\fs24 drichen lieby der folku\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 mnen menschen von ynnen vnd von vssnen.< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Nuon mercke, das die zaichen der folkuomnen goetlichen lieby der folkuomnen notturfftigkait}}\plain \f1\i\lang1033\fs24  vnd v\u180 \'b4bertreffenlichait sind zwayerlay, etliche v\u223 \'df der vssren wi\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 rckung vnd etliche v\u223 \'df der inren wirckung. Das erst zaichen der go\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 tlichen liebin der folku\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 mnen menschen na\plain \f1\i\super\lang1033\fs24 v\plain \f1\i\lang1033\fs24 ch dem vssren me \plain \f1\lang1033\fs24 [!] [11\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 wi\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 rcken ist, das der mensche berait ist sy\plain \f1\lang1033\fs24  [!] \plain \f1\i\lang1033\fs24 ze sterbend vmb das hail der\plain \f1\lang1033\fs24  (nachgetr.: \plain \f1\i\lang1033\fs24 andren\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 menschen ...\~\endash \~... Sanctus Paulus spricht: Wer got anhanget, der wirt ain gaist mit ym.\plain \f1\lang1033\fs24  }

