\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 70\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 72\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f2\caps\lang1033\fs24\chcbpat17 \u220 \'dcber die Gr\u246 \'f6\u223 \'dfe des Leidens Christi}}\plain \f2\caps\lang1033\fs24 .\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24 >Wa\plain \f1\i\super\lang1033\fs24 v\plain \f1\i\lang1033\fs24 rvmb das liden Ihesu Cristi gro\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 sser was denn kains andren menschen ye was vnd nimer wirt, das sind fil sa\plain \f1\i\super\lang1033\fs24 v\plain \f1\i\lang1033\fs24 che.< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Dv\u180 \'b4 erste sach, das das erwirdig liden vnsers lieben herren Ihesu Cristi vnsers}}\plain \f1\lang1033\fs24  [71\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 behalters das aller gro\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 st liden was, das was, das er o\plain \f1\i\super\lang1033\fs24 v\plain \f1\i\lang1033\fs24 n als mittel von got geformiert was in der iunckfro\plain \f1\i\super\lang1033\fs24 v\plain \f1\i\lang1033\fs24 wen Marie lib durch die wirckung des hailgen gaist von den aller zerttusten blu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 cztro\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 pflin vnder dem iunckfro\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 lichen herczen ...\~\endash \~... D\u250 \'fa sechzechet sa\plain \f1\i\super\lang1033\fs24 v\plain \f1\i\lang1033\fs24 ch was, das der herr Ihesus vnschuldigklichest gelitten ha\plain \f1\i\super\lang1033\fs24 v\plain \f1\i\lang1033\fs24 t das gro\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 st liden vnd grimesten to\plain \f1\i\super\lang1033\fs24 v\plain \f1\i\lang1033\fs24 de\plain \f1\lang1033\fs24 .  16 Gr\u252 \'fcnde, warum das Leiden Christi gr\u246 \'f6\u223 \'dfer als das jedes anderen Menschen war.}

