\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 a. (2\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 \u8722 -51\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 ) \plain \f1\caps\lang1033\fs22 \lquote \plain \f1\caps\lang1033\fs22 Revelatio nova itineris et passio\plain \f1\caps\lang1033\fs22 nis undecim milium virginum\plain \f1\caps\lang1033\fs22 \rquote \plain \f1\caps\lang1033\fs22 , deutsch.  \plain \f1\lang1033\fs22 >[H]\plain \f1\i\lang1033\fs22 ie vachet die epistel an zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs22  den jungfrowen Jhesu Cristi gemainlich v\u180 \'b4ber die hystorie der hailgen xi tussent ma\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs22 gt, die do geoffenbart ist von den selben himelschen jungfrowen.<\plain \f1\lang1033\fs22  [Rest der Seite leer.] (3\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 \u8722 -4\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  Vorrede:) \plain \f1\i\lang1033\fs22 Allen reinen jungkfrowen vnsers herren Jhesu Cristi vnd allen glo\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs22 bigen der hailgen kirchen bru\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs22 der T heil zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs22  der vnzergenglichen fro\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs22 den des ewigen lebens. In dem jare do man zalt von gottes gebu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs22 rt mccc vnd lxxxiii von in geben des herren vnd mittw\u252 \'fcrckung siner milten gebererin o\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs22 breste k\u250 \'fanigin so sind wir schriben ein n\u250 \'fawe hystorie von den xii tussent jungkfrowen ...\plain \f1\lang1033\fs22  (4\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 \u8722 -51\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  Text:) \plain \f1\i\lang1033\fs22 >Hie vacht an ain n\u250 \'fawe offenbarung der walfart vnd des lidens der xi tussent jungfrowen.<\plain \f1\lang1033\fs22  [4\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 ] \plain \f1\i\lang1033\fs22 Got, der do von ewigkait alle ding wislichen geordnet hett, hatt gesamlet mit sinem wisen rat vnd fu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs22 rsichtigkait die aller edlosten jungfrowen diser welt vnd hett sich gewirdiget die zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs22  laden zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs22  der himelschen br\u250 \'fatloff zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs22  verma\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs22 chlen sinem aingebornen sun ... \u8722 - ... Do ouch die selben jungfrowen nachen sint irem su\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs22 ssen br\u250 \'fattgom des obresten vatters aingeborner vnd lieber sun der gebenedicten\plain \f1\lang1033\fs22  [51\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 ] \plain \f1\i\lang1033\fs22 jungfrowen Maria vnd mitt im regyerentt in vnvssprechelicher ewiger fro\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs22 uden, der do ouch mitt siner lieben mu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs22 tter aller jungfrowen k\u250 \'fanigin gebenedyget vnd gelobt syg on end jemer ewenklichen. Amen.\plain \f1\lang1033\fs22   Lat. Vorlage: BHL 8433. Zum Verfasser des lat. Textes vgl. K. \plain \f1\scaps\lang1033\fs22 Koch\plain \f1\lang1033\fs22  / E. \plain \f1\scaps\lang1033\fs22 Hegel\plain \f1\lang1033\fs22 , Die Vita des Pr\u228 \'e4monstratensers Hermann Joseph von Steinfeld, K\u246 \'f6ln 1958, S. 105f.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset0 Cambria;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

