\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 5\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \plain \f1\caps\lang1033\fs24 Gereimtes \plain \f1\caps\lang1033\fs24 Gebet zum \plain \f1\caps\lang1033\fs24 Eigenengel\plain \f1\lang1033\fs24 .  \plain \f1\i\lang1033\fs24 Das ist dz engel liedle. Es hat ein sin, / min e\plain \f1\lang1033\fs24 [\plain \f1\i\lang1033\fs24 ngel\plain \f1\lang1033\fs24 ]\plain \f1\i\lang1033\fs24 , ich bin / dir gniegt so fast, / dz ich kain rast / on dich mag hon, / mich nitt verlon ...\~\~... engel, hochster hort, / vernim min wort, / din lieb vnd tr\u252 \'fcw / an mir ern\u252 \'fcw / zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  aller stund, / v\u223 \'df hertzen grund / zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\lang1033\fs24  [5\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 dir ich schry, / engel, mach mich fry, / vor allem fal / der s\u252 \'fcnden qual / behiett\plain \f1\lang1033\fs24  [?] \plain \f1\i\lang1033\fs24 mich in des himels sal. / Amen. Dz werd w\plain \f1\lang1033\fs24 [\plain \f1\i\lang1033\fs24 ar\plain \f1\lang1033\fs24 ].}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset0 Calibri;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 5\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 20\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \plain \f1\caps\lang1033\fs24 Allegorische Betrachtung von drei Ampeln\plain \f1\caps\lang1033\fs24 , mit Gebetsanweisungen\plain \f1\lang1033\fs24 .  \plain \f1\i\lang1033\fs24 Dy\u223 \'df sind dry costlich amplen. Die erst ampel ist von ainem lutteren karfunckel stain. Da by betracht\plain \f1\lang1033\fs24  [6\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 die allmechtigen krafft got des vatters, wie sin gewalt so machtiklich regniert himel vnd erd ...\plain \f1\lang1033\fs24  (8\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Die ander ampel ist von ainem luttren cristall, bed\u252 \'fct die hochen wyshait got des suns, mit der er f\u252 \'fclt vnd durchl\u252 \'fccht all creaturen, die all sch\u246 \'f6n gezirt vnd beklaid sind mit siner g\u246 \'f6tlichen wi\u223 \'dfhait ...\plain \f1\lang1033\fs24  (11\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Die drit vnd lest ampel ist von ainem luteren rubin, bed\u252 \'fct die s\u252 \'fcssen liebe got des hailgen gaist,\plain \f1\lang1033\fs24  [11\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 von der meng lutter hertz so inhitzcklich erl\u252 \'fccht vnd encz\u252 \'fcnt wirt mit warer erkantnus des liepsten willen gocz ...\plain \f1\lang1033\fs24  (15\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Dy\u223 \'dfe iii claren amplen soltu alli zitt zirlich brenen vor dem thron der hailgen dryualtikait zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  ainem ewigen gestifft f\u252 \'fcr all din versumnus vnd schuld in dem\plain \f1\lang1033\fs24  [16\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 g\u246 \'f6tlichen dienst, in der regel vnd in aller gaistlichait vnd solt zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  dy\u223 \'dfen iii amplen vnd liechter betten, als vil du gnad hast. Darnach vf Aparicio sancte Michaelis k\u252 \'fcnftiklich dz hopt\plain \f1\lang1033\fs24  [16\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 gu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 tt di\u223 \'dfer liechter anlegen by dem grossen f\u252 \'fcrsten vnd k\u252 \'fcng himelrichs vnd ertterichs ... vnd vber die\plain \f1\lang1033\fs24  [17\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 ersten amplen soltu zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  ainem heren vnd vogt setzen den grossen erczengel sant Michael vnd v\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 ber die anderen sant Gabriel, och v\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 ber die driten sant Raphael, dz sy allzit warnemit, sy sch\u246 \'f6n vnd clarlich vor gott sygent brinen ...\plain \f1\lang1033\fs24  (19\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Di\u223 \'df nachgeschriben gebet ist der zin\u223 \'df, den du all fron fasten solt geben: Davits ps\u228 \'e4lter i, Pater noster lxx, kurtz\plain \f1\lang1033\fs24  [20\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 vigilgen xv, die vii psalmen vii mal ... Stetit angelus c\plain \f1\lang1033\fs24  [CAO 5029], \plain \f1\i\lang1033\fs24 Asendet\plain \f1\lang1033\fs24  [!] \plain \f1\i\lang1033\fs24 fumus c\plain \f1\lang1033\fs24  [CAO 6124], \plain \f1\i\lang1033\fs24 Archangele c\plain \f1\lang1033\fs24  [CAO 1472], \plain \f1\i\lang1033\fs24 Te deum l, Miserere l, Pa\u223 \'dfion iiii, antifon O durissimum vii\plain \f1\lang1033\fs24 . }

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset0 Calibri;}{\f3\fnil\fcharset0 Times New Roman (Designüberschr;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 20\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 48\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \plain \f1\caps\lang1033\fs24 Gebete zum Eigenengel und zu den neun \plain \f1\caps\lang1033\fs24 Engelch\plain \f1\caps\lang1033\fs24 \u246 \'f6\plain \f1\caps\lang1033\fs24 ren\plain \f1\lang1033\fs24 .  \plain \f1\i\lang1033\fs24 Hie volget ain guldis kettemlin oder kr\u246 \'f6nle von allen engelschen gaisten. Erstlich ain lob vnd gebet von dinem aigne engel, nachgends x gebett, vnd von den ix c\u246 \'f6ren\plain \f1\lang1033\fs24  [21r] der englischen ritterschafftt.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 a. (21\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 25\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Zum Eigenengel. \plain \f1\i\lang1033\fs24 Ich loben, erren vnd gr\u250 \'facz dich, du min engelschliche zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 versicht, du l\u250 \'fachtendes liecht von gott vs\u223 \'df gangen\plain \f1\lang1033\fs24  [21\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 vnd in ewikait widervm inglenczend in sin tieffe abgru\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 nd, du liechter carfunnckel, du gilgen zartt ... Eya, du min engelschlich\plain \f1\lang1033\fs24 [22\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ]\plain \f1\i\lang1033\fs24 er vatter vnd h\u250 \'fatter von gott mir zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  geben vnd bevolchen ...\~\~... vnd belaitt mich sicherlich vs\u223 \'df di\u223 \'dfem ellend in dz ewig vatterland. Dar vm beger ich dich in zitt vnd ewikait ze loben vnd eren. Amen.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 b. (25\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 48\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Zu den neun Engelch\u246 \'f6ren. \plain \f1\i\lang1033\fs24 Eya mit hertz, sel vnd gem\u250 \'fatt lob, er vnd gru\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 tz ich v\u180 \'b4ch liechtrichen, brinnenden gaist seraphin, gantz enz\u250 \'fant vol f\u250 \'fars g\u246 \'f6ttlicher minn vnd liebe, o ir rotten ro\u223 \'dfen,\plain \f1\lang1033\fs24  [26\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 ir dursichtigs gold puliert in der es\u223 \'df gott des hailgen gaist ...\~\~... all ch\u246 \'f6r aller engelschen yerarchien\plain \f1\lang1033\fs24  [47\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 begeren ich ain ewig lob zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  enbietten vnd hie in zitt also zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  eren, ir min sel an minem jv\u180 \'b4ngsten s\u250 \'fafczen enpfachend, von dy\u223 \'dfem ellend f\u250 \'farend in die obresten frouden\plain \f1\lang1033\fs24  [?], \plain \f1\i\lang1033\fs24 vrsprung aller ding mit v\u180 \'b4ch on end\plain \f1\lang1033\fs24  [48\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 ze schowen, loben vnd nies\u223 \'dfen ewigcklichen. Amen\plain \f1\lang1033\fs24 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset0 Calibri;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 48\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 51\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \plain \f1\caps\lang1033\fs24 Gebet zum Eigenengel\plain \f1\lang1033\fs24 .  \plain \f1\i\lang1033\fs24 Aber ain gebett von dinem aignen engel. Eya, du l\u250 \'fachtender f\u250 \'farstlicher herr, du min aigner vnd geliepter engel, der du mir von gott\plain \f1\lang1033\fs24  [48\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 bist zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  geben zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  ainem h\u250 \'fatter vnd gelaitter, och beschirmer, ich bitt dich, stand mir by h\u250 \'fat vnd allwegents ...\~\~... vnd presentier min sel f\u250 \'far gottes angesicht, da ich inn mit dir ewigcklich on end werd loben, schowen vnd nies\u223 \'dfen. Amen.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset0 Calibri;}{\f3\fnil\fcharset0 Times New Roman (Designüberschr;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 51\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 62\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \plain \f3\caps\lang1033\fs24 Barbara-Offizium, lat.\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24 De sancto\plain \f1\lang1033\fs24  [!] \plain \f1\i\lang1033\fs24 Barbara cur\u223 \'df\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Domine, labia mea\plain \f1\lang1033\fs24  [51\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 aperies et os meum annuniabit ... Deus in adiutorium meum intende ... Miserere mei, deus, martire pro Barbara regina ...\plain \f1\lang1033\fs24  (52\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Gloria patri ... \plain \f1\lang1033\fs24 (52\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 60\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 )\plain \f1\i\lang1033\fs24  Mattutino tempore Barbara beata / in obscuro carcere fuit illustrata ...\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Hora conpletorii\plain \f1\lang1033\fs24  [59\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 a patre decollata / filia Dioscuri fuit tumulata / et per manus angeli deo presentata, / anima Dioscuri inge\plain \f1\lang1033\fs24  [lies: \plain \f1\i\lang1033\fs24 igne\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 devorata. Versus. Ora pro me, ut sim dingna. Colect. Deus, qui beatam. Has horas can\plain \f1\lang1033\fs24 [60\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ]\plain \f1\i\lang1033\fs24 onicas Barbara regina / ferro tibi debitas, ut a repentina / plaga me custodias atque a rapina / demonis me protegas et celum  propina. Amen\plain \f1\lang1033\fs24  [AH 30, S. 146, Nr. 61]. \plain \f1\i\lang1033\fs24 Antiff von sancta Barbara. Sponsa Cristi Barba\plain \f1\lang1033\fs24 [60\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ]\plain \f1\i\lang1033\fs24 ra / gaudet inter verbera ..\plain \f1\lang1033\fs24 . [auch M\u252 \'fcnchen, BSB, Clm 28346, Bl. 226\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ; vgl. \plain \f1\scaps\lang1033\fs24 Glauche\plain \f1\lang1033\fs24  1984, S. 138; nicht in CAO oder AH]. \plain \f1\i\lang1033\fs24 Collect. Ostende in nobis, domine, tue pietatis virtutem ... et ad te pia devocione et leticia gradiamur. Per dominum Jhesum.\plain \f1\lang1033\fs24  }

