\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 105\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 106\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \plain \f1\caps\lang1033\fs24 Ablassgebet\plain \f1\lang1033\fs24 .  \plain \f1\i\lang1033\fs24 Dis nachgend gebett hatt hundert tag applas. O herr, sprich\plain \f1\lang1033\fs24  [105\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 din g\u246 \'f6ttlich wortt in mich vnd gib mir es zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  heren. O herr entz\u250 \'fand din go\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 ttlich liecht in mir ...\~\endash \~... vnd thu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  mich es ewigcklich behaltten. Amen.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman (Designüberschr;}{\f2\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f2\lang1033\fs24 106\plain \f2\super\lang1033\fs24 r\plain \f2\lang1033\fs24 171\plain \f2\super\lang1033\fs24 v\plain \f2\lang1033\fs24  \plain \f1\caps\lang1033\fs24 Gebete zu Maria und dem Jesuskind in der Adventszeit und zu Weihnachten\plain \f2\lang1033\fs24 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman (Designüberschr;}{\f2\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f2\lang1033\fs24 a. (106\plain \f2\super\lang1033\fs24 r\plain \f2\lang1033\fs24 114\plain \f2\super\lang1033\fs24 r\plain \f2\lang1033\fs24 ) Zehn Lobpreisungen Marias in der Adventszeit.  \plain \f2\i\lang1033\fs24 Di\u223 \'df ist ain sch\u246 \'f6n gebett von vn\u223 \'dfer lieben frowen, dar mit man si sol grietzen alle tag\plain \f2\lang1033\fs24  [106\plain \f2\super\lang1033\fs24 v\plain \f2\lang1033\fs24 ] \plain \f2\i\lang1033\fs24 in dem hailgen advent, do sy dz ewig wort vnder irem rainen hertzen beschlossen hat vnd vff ain jetliche lobung sprich ain Ave Maria oder was du gern wilt.\plain \f2\lang1033\fs24  [107\plain \f2\super\lang1033\fs24 r\plain \f2\lang1033\fs24 ] \plain \f2\i\lang1033\fs24 Ich loben dich, k\u250 \'fange der himel, ain frow der engel ain mu\plain \f2\i\super\lang1033\fs24 o\plain \f2\i\lang1033\fs24 tter der barmhertzikait, dz du bist dz wunicklich bl\u250 \'fagend para\plain \f2\lang1033\fs24 [47\plain \f2\super\lang1033\fs24 v\plain \f2\lang1033\fs24 ]\plain \f2\i\lang1033\fs24 dis, in dem gewachsen ist der lebendig bom ...\plain \f2\lang1033\fs24  (107\plain \f2\super\lang1033\fs24 v\plain \f2\lang1033\fs24 ) \plain \f2\i\lang1033\fs24 Ich loben dich,\plain \f2\lang1033\fs24  [108\plain \f2\super\lang1033\fs24 r\plain \f2\lang1033\fs24 ] \plain \f2\i\lang1033\fs24 frow, du s\u250 \'fa\u223 \'dfe mu\plain \f2\i\super\lang1033\fs24 o\plain \f2\i\lang1033\fs24 tter gotz, dz du bist dz gu\plain \f2\i\super\lang1033\fs24 o\plain \f2\i\lang1033\fs24 tt fruchtbar erterich ...\~\endash \~... als es gezam dem adel der go\plain \f2\i\super\lang1033\fs24 e\plain \f2\i\lang1033\fs24 tt\plain \f2\lang1033\fs24 [114\plain \f2\super\lang1033\fs24 r\plain \f2\lang1033\fs24 ]\plain \f2\i\lang1033\fs24 lichen gerechtikait vnd es iesch vnd vorderet die gottlich gerechtkait zu\plain \f2\i\super\lang1033\fs24 o\plain \f2\i\lang1033\fs24  wider br[r]ingend menschliche nattur. Amen.\plain \f2\lang1033\fs24   }

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman (Designüberschr;}{\f2\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f2\lang1033\fs24 b. (114\plain \f2\super\lang1033\fs24 r\plain \f2\lang1033\fs24 126\plain \f2\super\lang1033\fs24 r\plain \f2\lang1033\fs24 ) \plain \f1\lang1033\fs24 Gebet zur Verk\u252 \'fcndigung an Maria.\plain \f2\lang1033\fs24  \plain \f2\i\lang1033\fs24 >Von dem loblichen hochzit der menschwerdung Cristi vnd\plain \f2\lang1033\fs24  [114\plain \f2\super\lang1033\fs24 v\plain \f2\lang1033\fs24 ] \plain \f2\i\lang1033\fs24 von dem gebet der verk\u250 \'fandung.< By\u223 \'df wilkumen, hocher Gabriel, himelscher trostlicher verk\u250 \'fander, edler werber, wi\u223 \'dfer briefftrager ...\plain \f2\lang1033\fs24  (115\plain \f2\super\lang1033\fs24 v\plain \f2\lang1033\fs24 ) \plain \f2\i\lang1033\fs24 >Ave Maria, gracia plena, dominus tecum.< O s\u250 \'fa\u223 \'dfer gru\plain \f2\i\super\lang1033\fs24 o\plain \f2\i\lang1033\fs24 z, o s\u250 \'fander bu\plain \f2\i\super\lang1033\fs24 o\plain \f2\i\lang1033\fs24 \u223 \'df, o quellender brunn vns\u223 \'dfers hails ...\~\~... Zu\plain \f2\i\super\lang1033\fs24 o\plain \f2\i\lang1033\fs24  dem f\u250 \'far vns, raine magt, dem sig lob vnd\plain \f2\lang1033\fs24  [126\plain \f2\super\lang1033\fs24 r\plain \f2\lang1033\fs24 ] \plain \f2\i\lang1033\fs24 er geset in ewigkait. Amen.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman (Designüberschr;}{\f2\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f2\lang1033\fs24 c. (126\plain \f2\super\lang1033\fs24 r\plain \f2\lang1033\fs24 136\plain \f2\super\lang1033\fs24 r\plain \f2\lang1033\fs24 ) Gebet zur schwangeren Maria in der Adventszeit.  \plain \f2\i\lang1033\fs24 Di\u223 \'df ist ain sch\u246 \'f6n gebett, in dem gelopt wirt die schwanger jungfro Maria, vnd mag man es sprechen in dem advent. O du vnv\u223 \'dfspre\plain \f2\lang1033\fs24 [126\plain \f2\super\lang1033\fs24 v\plain \f2\lang1033\fs24 ]\plain \f2\i\lang1033\fs24 chenliche wirdige Maria, ich loben dich vnd gr\u250 \'fatz dich mit ganczem fli\u223 \'df, vnd mit innicklicher begird mins herczen loben vnd anbetten dich ...\~\~... dich sol loben ain ietliche zung der welt vnd der gerecht\plain \f2\lang1033\fs24 [136r]\plain \f2\i\lang1033\fs24 en vnd der selgen von welt zu\plain \f2\i\super\lang1033\fs24 o\plain \f2\i\lang1033\fs24  welt imer vnd ewicklichen. Amen.\plain \f2\lang1033\fs24   Parallel\u252 \'fcberlieferung: Karlsruhe, BSB, Cod. St. Peter pap. 8, Bl. 91\plain \f2\super\lang1033\fs24 v\plain \f2\lang1033\fs24  (Freiburg, Dominikanerinnen St. Agnes, 2. H\u228 \'e4lfte 16. Jh. [um 15501560]; vgl. \plain \f2\scaps\lang1033\fs24 Niebler\plain \f2\lang1033\fs24  1969, S. 13). }

