\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 i. (155\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 166\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Sieben Freuden Marias an Weihnachten.  \plain \f1\i\lang1033\fs24 Die sibent\plain \f1\lang1033\fs24  [!] \plain \f1\i\lang1033\fs24 fr\u246 \'f6d, die vnser liebe frow in der wichn\u228 \'e4cht nacht hat.\plain \f1\lang1033\fs24  [156\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 Die erst ermanung iren lib vnverma\u223 \'dfgeten sel. O frow der glori vnd k\u250 \'fange der himel ... iungfrow Maria, ich ermanen dich der gros\u223 \'dfen fr\u246 \'f6d vnd gnaden, mit denen din m\u228 \'e4gtlicher lib vnd din\plain \f1\lang1033\fs24  [156\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 clare edle sel was v\u180 \'b4bergos\u223 \'dfen ...\plain \f1\lang1033\fs24  (164\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Die vii ermanung iren hailgen oren. O wol gezirtter temp\plain \f1\lang1033\fs24 [164\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ]\plain \f1\i\lang1033\fs24 el, ain wolgefellige wonung vnd ru\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 w statt der hochen drifalttikait, ich arme s\u250 \'fandere ermanen dich der gro\u223 \'dfen fr\u246 \'f6den, die du hettest, da du mit dinen rainen oren h\u246 \'f6rtest die s\u250 \'fassen melody ...\~\~... enpfach min arme sel vnd dz ich arme s\u250 \'fandere durch din aller hailgestes firbit von im gn\u228 \'e4digcklich enpfangen\plain \f1\lang1033\fs24  [166\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 werd vnd von dir vnd von im nimer geschaiden werd. Amen.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 k. (166\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 168\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Weihnachtsgebet Bernhards von Clairvaux.  \plain \f1\i\lang1033\fs24 Dis gebett lertt vn\u223 \'dfer her sant Bernhard alles an der hailgen wihen\u228 \'e4cht nach. Naig dich dem\u250 \'fatticklich f\u250 \'far die f\u250 \'fa\u223 \'df des kindle Ihesus in dem criple vnd gru\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 cz es mit and\u228 \'e4chtigem hertzen vnd sprich also.\plain \f1\lang1033\fs24  [166\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 Gegr\u250 \'fa\u223 \'dfet vnd gebenedyet sigestu, gemintes kindle Jhesus, in dem v\u228 \'e4tterlichen hertzen, dar v\u223 \'df dich minn vnd liebe gezogen hat in die scho\u223 \'df der jungfrowen Marie ...\plain \f1\lang1033\fs24  Vgl. Bernhard von Clairvaux zugeschriebener Hymnus AH 31, S. 26\endash 30, Nr. 23 (Ad Christum infantem).}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 l. (168\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 171\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Gebet zum Jesuskind.  \plain \f1\i\lang1033\fs24 Die wil du also genaigt bist in diner begird vor dem s\u250 \'fa\u223 \'dfen kindle Jhesu, so bitt das milt kindle mit andacht, was du begerst, vnd also oder des gelichen. O gnadriches kindle, o du m\u228 \'e4gtliche ge\plain \f1\lang1033\fs24 [168\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ]\plain \f1\i\lang1033\fs24 bu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 rtt, du edler lilie jungfr\u246 \'f6licher rainikait vnd ain lieplicher liebhaber vnd volbringer der menschlichen sa\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 likait, gedenck, wie dich minn vnd liebe gezogen hatt von dem v\u228 \'e4tterlichen hertzen ...\~\~... Her, ich bin ingangen in miner vnschuld, erbarm dich v\u180 \'b4ber mich vnd erl\u246 \'f6\u223 \'df vns. Amen.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset0 Times New Roman (Designüberschr;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;}

\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 171\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 184\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \plain \f2\caps\lang1033\fs24 Gebet zur Himmelfahrt Marias.\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24 Ain sch\u246 \'f6n gebett von vn\u223 \'dfer lieben frowen himelfart. Wol vff, min gem\u250 \'fat vnd aller miner sel crefftt, wol vff, mein sel, bis\plain \f1\lang1033\fs24  [172\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 vnverzagt in inerlichen fr\u246 \'f6den ...\plain \f1\lang1033\fs24  (173\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Sprich: O mu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 tter der gnaden, o k\u250 \'fangin der barmhertzigkait, o frow der himel ...\plain \f1\lang1033\fs24  (174\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 h\u250 \'fatt sich herab zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  vns, dine erbarmhertzigen ogen blickent vns an in valckes blick ...\plain \f1\lang1033\fs24  (177\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Ave Maria,\plain \f1\lang1033\fs24  [177\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 himelschliche kai\u223 \'dferin, bis gegr\u250 \'fatzt vnd ermanet der sunderlichen fr\u246 \'f6den ...\~\~... Nach des schiffs bruch hoffent wir schuldige su\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 nder die cron der eren zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  besitzen vnd die ewigen ru\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 w. Ora pro nobis.\plain \f1\lang1033\fs24  Anschlie\u223 \'dfend Collecta: \plain \f1\i\lang1033\fs24 Collectt. Deus qui per beattissimam virginem Mariam, matrem tuam, humanum genus re\plain \f1\lang1033\fs24 [184\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ]\plain \f1\i\lang1033\fs24 staurasti ... presta, ques\u223 \'dfumus, ut ejus interveritu\plain \f1\lang1033\fs24  [?] \plain \f1\i\lang1033\fs24 coram sede myestatis tue corona perfrui mereamur eterna. Qui vivis ... Amen. Fiat. Amen.}

