\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 30\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 31\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 Lateinische Hymnenstrophen}}\plain \f1\lang1033\fs24 .  \plain \f1\i\lang1033\fs24 Jhesu, via, veritas, fons, inmensa pietas ... \plain \f1\lang1033\fs24 \endash  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 O Maria, omnis sanctus te honorat}}\plain \f1\i\lang1033\fs24 , Jhesus Cristus te coronat in celesti gloria ..\plain \f1\lang1033\fs24 . [vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 AH 32, S. 154, Nr. 108,5}}\plain \f1\lang1033\fs24 ] \endash  {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ave, rex celorum, splendor patris}}\plain \f1\i\lang1033\fs24  ... \plain \f1\lang1033\fs24 \endash  {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Paschalis agnus cernitur, vetustum pascha spernitur}}\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 ... \endash  {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Sacramentum mirabile }}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [31v]}}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 , opus tam ineffabile}}\plain \f1\lang1033\fs24  ... \plain \f1\i\lang1033\fs24 Ave, mundissime domine Jhesu Criste, princeps pacis, janua celi, panis vivus\plain \f1\lang1033\fs24  ... Bis auf die zweite keine der Strophen in AH nachweisbar.}

