\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 31\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 33\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 Osterhymnus}}\plain \f1\lang1033\fs24 .  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Surgit Cristus cum tropheo, jam ex agno factus leo solempni victoria}}\plain \f1\i\lang1033\fs24  ...\~\endash \~... Scimus Cristum surrexisse ex mortuis vere; tu nobis victor rex miserere. Alleluia.\plain \f1\lang1033\fs24   Edition (z.\~T. leicht abweichend): {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 AH 54, S. 364f., Nr. 230,1\endash 15}}\plain \f1\lang1033\fs24 . }

