\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 33\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 57\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 F\u252 \'fcnfzig Lobpreisungen des Auferstandenen, dt.-lat}}\plain \f1\caps\lang1033\fs24 .\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ich loben dich vnd gr\u252 \'fctz vnd glorifizier vnd anbetten dich}}\plain \f1\i\lang1033\fs24 , du h\u246 \'f6chsti, wunsamesti vnd vngemessni ewige gotthait, die so adelich verborgen litt in Jhesum, v\u180 \'b4nssrem ainigen lieb vnd gemachel. Salve festa dies, toto venerabilis evo, qua deus infernum vicit et astra tenet\plain \f1\lang1033\fs24  [{\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 AH 50, S. 79 (Nr. 69)}}\plain \f1\lang1033\fs24  = {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Cantus-DB a00177}}\plain \f1\lang1033\fs24 ]. \plain \f1\i\lang1033\fs24 Resurrexit Cristus, qui crucifixus est in ara, qui pascalis victima vivens est oblata hostia. Alleluja.\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Ich loben dich, du aller s\u252 \'fcssestes lieb, vnd gr\u252 \'fctz dich, du ewiger trost, won du bist ain schin der va\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 tterlichen glori ...\~\plain \f1\lang1033\fs24 \endash \~\plain \f1\i\lang1033\fs24 ..\plain \f1\lang1033\fs24 . (Ende der dt. Gebete 55\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 :) \plain \f1\i\lang1033\fs24 da mit ich verdien sy nach dissem zit in dem himelschen hof mit den cherubinschen vnd seraphischlichen gaisten in volku\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 ner\~\plain \f1\lang1033\fs24 [!]\plain \f1\i\lang1033\fs24  vercl\u228 \'e4rung sel vnd libs sig schowen vnd \plain \f1\lang1033\fs24 [55\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ]\plain \f1\i\lang1033\fs24  loben von ewen ze ewen. Amen, fiat.\plain \f1\lang1033\fs24  57\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  als Abschluss lat. Gebet: {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Deus, qui nos resurrexcionis dominice annua solempnitate letificas}}\plain \f1\i\lang1033\fs24 , concede propicius, ut per temporaliter festa, que agimus, pervenire ad gaudia eterna mereamur. Per dominum.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 50 kurze Lobpreisungen bzw. Gr\u252 \'fc\u223 \'dfe an den Auferstandenen. Nach jedem Gru\u223 \'df der Gesang \plain \f1\i\lang1033\fs24 Salve festa dies\plain \f1\lang1033\fs24 . Nach jedem 10. Gru\u223 \'df ein lateinischer Hymnus: (37\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ad cenam agni providi et stolis albis candidi post transitum maris rubri}}\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24  [{\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 AH 51, S. 87, Nr. 83}}\plain \f1\lang1033\fs24 ]. (41\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 42\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Mundi renovacio nova parit gaudio resurgenti domino conresurgunt omnia elementa serviunt}}\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24  [{\field{\*\fldinst HYPERLINK "hida://bezlit[3].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 AH 54, S. 224f., Nr. 148,1\endash 7}}\plain \f1\lang1033\fs24  (Autor: Adam de S. Victore)]. (45\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Aurora lucis ruttilat, celum laudibus intonat}}\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24  [{\field{\*\fldinst HYPERLINK "hida://bezlit[4].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 AH 51, S. 89, Nr. 84,1\endash 4}}\plain \f1\lang1033\fs24 ]. (49\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Mane prima sabati surgens dei filius nostra spes et gloria victor regem celeris rediit}}\plain \f1\i\lang1033\fs24  ab infe\plain \f1\lang1033\fs24 = [{\field{\*\fldinst HYPERLINK "hida://bezlit[5].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 AH 54, S. 214, Nr. 1431\endash 2}}\plain \f1\lang1033\fs24 ], bricht mit Seitenwechsel ab, danach (49\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 50\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Victime pascali laudes immolant cristianam}}\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24  [{\field{\*\fldinst HYPERLINK "hida://bezlit[6].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 AH 54, S. 12, Nr. 7}}\plain \f1\lang1033\fs24 ]. (55\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 57\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Rex regum dei agne leo Juda magne dux es virtutum mors peccati vita justicie}}\plain \f1\i\lang1033\fs24  .\plain \f1\lang1033\fs24 .. [{\field{\*\fldinst HYPERLINK "hida://bezlit[7].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 AH 50, S. 311f., Nr. 240}}\plain \f1\lang1033\fs24 ].}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset0 Times New Roman (Designüberschr;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 57\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 78\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f2\caps\lang1033\fs24\chcbpat17 F\u252 \'fcnfzig Gr\u252 \'fcsse zu den Freuden Marias bei der Auferstehung Ihres Sohns, dt.-lat}}\plain \f2\caps\lang1033\fs24 .\plain \f2\caps\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Regina celorum, gaude, inclita digna laude}}\plain \f1\i\lang1033\fs24 . Gaude, celi gema fulgida\plain \f1\lang1033\fs24  ... [{\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 AH 10, S. 82f., Nr. 98}}\plain \f1\lang1033\fs24 ]. (58\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ich loben dich, du himelschlicher m\u246 \'f6r stern}}\plain \f1\i\lang1033\fs24 , des minniklichen verlangens, so din zart mu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 tterlich hertz hatt nach der vrstende vnd zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 ku\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 nft dins aller gemintosten suns. Regina celi. Ich loben dich, du f\u250 \'farl\u250 \'fachtendes mette gestiern, daz die g\u246 \'f6ttlich vermugenhait allain in der woll gezierten arch dins ed\plain \f1\lang1033\fs24 [59\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ]\plain \f1\i\lang1033\fs24 len hertzen lag verborgen, wonn du allain creftigklich gelobtest, dz din sun warlich vom tod wu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 rd vff erston ... \plain \f1\lang1033\fs24 Als Schluss des dt. Textes 75\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 77\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Gebet, in dem der Bezug zur Auferstehung hergestellt wird: {\field{\*\fldinst HYPERLINK "hida://5650[2].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ich gr\u252 \'fctz dich, du k\u250 \'fangin der }}{\field{\*\fldinst HYPERLINK "hida://5650[2].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [76}}{\field{\*\fldinst HYPERLINK "hida://5650[2].5666d/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 r}}{\field{\*\fldinst HYPERLINK "hida://5650[2].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 ]}}{\field{\*\fldinst HYPERLINK "hida://5650[2].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  engel}}\plain \f1\i\lang1033\fs24 , ich loben dich, du kaisserrin aller hailgen ... der hochen tieffen fr\u246 \'f6d, die din zart edel hertz, sel vnd lib jetzent entpfancht von der g\u246 \'f6ttlichen signuft dins geminten suns, wan du nun mit hochster geniegt bist schowen, loben vnd nie\u223 \'dfen die adelkait, richait vnd wunnsamkait der frucht\plain \f1\lang1033\fs24 [76\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ]\plain \f1\i\lang1033\fs24 barkait der vrstende dins suns ..., dz ich hie in dissem zitt dz v\u180 \'b4berw\u250 \'fardig, aller hochgelobtest, wunsam, g\u246 \'f6ttlich fest der g\u252 \'fcnlichen, glorioslichen, k\u250 \'fangklichen vrstende dins kaiserlichen suns\plain \f1\lang1033\fs24  [77\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 also in h\u250 \'fatzciger begierd, h\u246 \'f6chster fr\u246 \'f6d sig loben, eren, glorifizieren vnd erh\u246 \'f6chen, dz ich in dem ewigen vatterland mit allen engelschlichen gaisten vnd himelschlichen burger sy sig loben, schowen vnd niessen in clarhait sel vnd libs. Amen.\plain \f1\lang1033\fs24  Danach lat. Hymnenstrophen und Gebet: (78\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Virgini Marie laudes concina\plain \f1\lang1033\fs24 [n]\plain \f1\i\lang1033\fs24 t cristiani. {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 O beata domina, tua per precamina reconcilientur peccatores}}\plain \f1\lang1033\fs24  ... [{\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 AH 54, S. 31f., Nr. 21}}\plain \f1\lang1033\fs24 ]. {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Gaude rosa speciosa, super omnis amorosa}}\plain \f1\i\lang1033\fs24 , tu es rosa singularis, sola rosa tu vocaris, tu lilium et fiola, alleluja\plain \f1\lang1033\fs24   [{\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 AH 32, S. 93, Nr. 63, Str. 16, 1. H.}}\plain \f1\lang1033\fs24 ]. \plain \f1\i\lang1033\fs24 >Oracio.< {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Deus, qui per gloriosam resurrexionem vnigeniti filii tui, domini nostri Jhesu Cristi, familiam tuam letificare dignatus es}}\plain \f1\i\lang1033\fs24 ,\plain \f1\lang1033\fs24  [78\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 presta, quesumus, ut per venerabilem eius genitricem virginem Mariam perpetue vite gaudia consequamur, per eundem Jhesum Cristum dominum.\plain \f1\lang1033\fs24  
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 Auch \u252 \'fcberliefert in {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Cod. St. Georgen 42}}\plain \f1\lang1033\fs24 , Bl. 2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 61\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  (mit einigen Abweichungen); Abdruck nach St. Georgen 42: Alfred \plain \f1\scaps\lang1033\fs24 Holder\plain \f1\lang1033\fs24 , Altdeutsche Gebete, in: Alemannia 4 (1877), S. 86\endash 106, hier S. 86\endash 92 (1. Mariengr\u252 \'fc\u223 \'dfe). \endash  50 Lobpreisungen Marias, u.\~a. durch Vergleich mit Himmelsgestirnen, Edelsteinen und Blumen. Nach jedem Preis Hymnus \plain \f1\i\lang1033\fs24 Regina celorum\plain \f1\lang1033\fs24 . (s.\~o.). Nach jedem 10. Gru\u223 \'df der Gesang (60a\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[6].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Salve, imperatrix, matter Ihesu Cristi}}\plain \f1\i\lang1033\fs24 . O gloriosa domina, que virgo Maria extitit plena gracia filio compassa amoris est incendio resurgenti amplexans osculans cum gaudio. Alleluja, alleluja\plain \f1\lang1033\fs24 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset0 Times New Roman (Designüberschr;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 78\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 114\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f2\caps\lang1033\fs24\chcbpat17 zyklus (}}{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f2\i\caps\lang1033\fs24\chcbpat17 krentzlin}}{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f2\caps\lang1033\fs24\chcbpat17 ) von f\u252 \'fcnfzig Gebeten zur Himmelfahrt Christi, dt.-lat}}\plain \f2\caps\lang1033\fs24 .
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (78\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 81\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Einf\u252 \'fchrung (rot unterstrichen). \plain \f1\i\lang1033\fs24 Hie nach folget ain sch\u246 \'f6ns krentzlin von dinem herren vnd gott, dz du im machent\plain \f1\lang1033\fs24 \~[!] \plain \f1\i\lang1033\fs24 solt vnd in da mit zieren vff sin aller h\u246 \'f6chstes fr\u246 \'f6denrichostes fest siner jubilierenden gewaltigen himelfart, dz er von dir, siner gesponsen, ain sunder clainet k\u252 \'fcnde z\u246 \'f6gen gott, sinem himelschen vatter ...\~\endash \~...vnd die senende qual aller gottminnenden hertzen ze kumen zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  irem ainigen lieb vnd mit im vff ze faren. Bett ain Te deum, f\u250 \'far die sch\u246 \'f6nen r\u246 \'f6sli dis nach genden gr\u252 \'fctzli, f\u252 \'fcr die stil vnd bv\u180 \'b4tzli in den r\u246 \'f6slin die latininen versli.\plain \f1\lang1033\fs24  
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (81\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 114\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Gebete. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ich gr\u252 \'fctz, loben vnd glorificier dich, du vss geberende wider ingeberende krafft des v\u228 \'e4tterlichen hertzen}}\plain \f1\i\lang1033\fs24 , du min ainiger\plain \f1\lang1033\fs24  [81\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 trost, dz in dir ist die all vermugent krafft des g\u246 \'f6tlichen gewaltz, in dem du vermacht mit kaiserlicher herschaft alle ding ... Ich loben dich, du wider glentzender schin des ewigen liechts, dz du din zarte edle menschait vmm geben vnd ziert hast mit der durch l\u250 \'fachten clarhait des g\u246 \'f6ttli\plain \f1\lang1033\fs24 [81\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ]\plain \f1\i\lang1033\fs24 chen liechts vnd in v\u228 \'e4tterlicher tr\u250 \'faw by v\u180 \'b4ns gewonet von diner glorioslichen vrstende bis zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  diner jubilierenden himelfart ...\~\endash \~... vnd hilf mir, dz ich mich in allen tugenden v\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 b vnd in and\u228 \'e4chtiger betrachtung, dz in der inwendikait mins hertzen vnd sel alle zit syg wonen der hailig gaist mit allen sinen gaben vnd gnaden, mit der ich verbring alle mine wort vnd werck, dz ich verdiene nach dissem zit ze \plain \f1\lang1033\fs24 [114\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 kumen zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  dir, minem allerliepsten lieb, da ich dich in wunn, fr\u246 \'f6d schowen vnd niessen werd on end in ewiger ewikait. Et convesscens precepit eis, ab Jerosoloimis ne abirent, sed expectarent promissa munera\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 50 kurze Gebetsgr\u252 \'fc\u223 \'dfe an Christus. Nach jedem Gru\u223 \'df lat. Gebete, Bibellesungen, Responsorien, Antiphonen und Hymnenstrophen, u.\~a. (81\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 O potentissime domine, tu es inperialis mayestas}}\plain \f1\i\lang1033\fs24 , et data est tibi omnis potestas in celo et in terra super omnia\plain \f1\lang1033\fs24 . (81\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Iam quadraginta postquam surrexerat diebus sacris confirmans pectora apostolorum pacis cara relinquens oscula}}\plain \f1\lang1033\fs24 . (82\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ponis nubem ascensum tuum, domine}}\plain \f1\i\lang1033\fs24 , qui ambulas super pennas ventorum, alleluia, alleluia\plain \f1\lang1033\fs24  [{\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 CAO 7392}}\plain \f1\lang1033\fs24 ]. (82\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Accipiens de paradiso terrestri sanctos patres et illas sancte animas}}\plain \f1\lang1033\fs24 . (83\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[5].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Cum dilexisset suos, in finem dilexit eos, venit ad discipulos}}\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24  (83\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[6].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Voluit ante discessum suum prandere cum illis}}\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24  (84\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[7].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Omnes gentes plaudite, festos, choros ducite Cristo triumphante}}\plain \f1\lang1033\fs24  [{\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 AH 54, S. 232, Nr. 152, Str. 1}}\plain \f1\lang1033\fs24 ]. (86\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[8].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Tempus est, ut revertar ad eum, qui misit me, dicit dominus}}\plain \f1\i\lang1033\fs24 , nolite contristari, nec turbetur cor vestrum, rogo pro vobis patrem, ut ipse vos custodiat, alleluia, alleluia\plain \f1\lang1033\fs24  [{\field{\*\fldinst HYPERLINK "hida://bezlit[2].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 CAO 7758}}\plain \f1\lang1033\fs24 ]. (86\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[9].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Nisi ego abiero, paraclitus non veniet}}\plain \f1\i\lang1033\fs24 , dum assumptus fuero, mittam vobis, alleluia\plain \f1\lang1033\fs24  [{\field{\*\fldinst HYPERLINK "hida://bezlit[3].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 CAO 3882}}\plain \f1\lang1033\fs24 ].}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset0 Times New Roman (Designüberschr;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 114\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 121\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f2\caps\lang1033\fs24\chcbpat17 Mystisch gef\u228 \'e4rbte Betrachtung zur Himmelfahrt Christi}}\plain \f2\caps\lang1033\fs24 .\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Uf den h\u250 \'fattigen durchl\u250 \'fachten, wider glentzenden, himelschen vnd engelschlichen, clarifizierten, fr\u246 \'f6drichesten tag}}\plain \f1\i\lang1033\fs24 ,\plain \f1\lang1033\fs24  [114\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 an dem der strittbar ritter, der f\u252 \'fcrst des frids, der k\u250 \'fang der signuft, der kaiserlich regierer himelrichs vnd ertrichs, vss ewiger gewaltsamkait siner g\u246 \'f6ttlichen vermugenhait vnd vss aigner craft siner ewigen frighait sich wider vmm in adelkait siner verkl\u228 \'e4rten menschait hat presentiert in die g\u246 \'f6ttlichen himelschlichen schatzkamer\plain \f1\lang1033\fs24  [115\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 des v\u228 \'e4tterlichen hertzen ...\~\endash \~... dz es dir alles helf, dz ewig vnergr\u250 \'fantlich gu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 tt loben, das es sich selbs gerichet vnd geedlet hat f\u250 \'far all creaturen besunder h\u252 \'fct an dissem\plain \f1\lang1033\fs24  [121\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 g\u252 \'fcnlichen tag siner loblichen vff fart, in der er sich erh\u246 \'f6cht hat v\plain \f1\i\super\lang1033\fs24 \u180 \'b4\plain \f1\i\lang1033\fs24 ber alle geschaffne ding in dz tiefost der gotthait, da on underlas in spillender minn vom vatter geboren wirdt, darinn vnsser h\u246 \'f6chste s\u228 \'e4likait litt. Hie antwu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 rt sich das end dem anfang. Procedentem a patre tamquam sponsus de thalamo suo. Filius meus es tu, ego hodie genui te. Nun jetz vocat pater\plain \f1\lang1033\fs24  [121\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 filium ad consessus solium, donec sub pedaneos victos vel spontaneos ponat inimicos etc.\plain \f1\lang1033\fs24  (danach unterstrichen:) \plain \f1\i\lang1033\fs24 Vff dissen himelschen tag bett mit gird dins hertzen die loblichen sequen\u223 \'df Omnes gentes vnd Alfa et O.}

