\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 15\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 20\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 Gebet zum Namen Jesu}}\plain \f1\caps\lang1033\fs24  \plain \f1\caps\lang1033\fs24 ({\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 Anselm von Canterbury}}\plain \f1\caps\lang1033\fs24 : \plain \f1\caps\lang1033\fs24 '{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 O bone Jhesu, o dulcissime Jhesu}}\plain \f1\caps\lang1033\fs24 '\plain \f1\caps\lang1033\fs24 , dt.).\plain \f1\lang1033\fs24  unmittelbar an den Gebetszyklus anschlie\u223 \'dfend:) \plain \f1\i\lang1033\fs24 Vnd enmitten dissem \plain \f1\lang1033\fs24 [!]\plain \f1\i\lang1033\fs24  scho\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 nen r\u246 \'f6sen\plain \f1\lang1033\fs24  [16\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 sol lygen ain edler karfunc|lel\plain \f1\lang1033\fs24  [!], \plain \f1\i\lang1033\fs24 dz ist der su\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 s n\u228 \'e4m Jhesus. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 O gu}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs24\chcbpat17 o}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 ttiger Jhesus, o begirlichoster Jhesus, o aller su}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs24\chcbpat17 e}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 stester }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [!]}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  Jhesus}}\plain \f1\i\lang1033\fs24 , o Jhesus, ain sunn der junngfr\u246 \'f6wen Maria, vol gu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 ttikait vnd barmherikaitt\plain \f1\lang1033\fs24  [!], \plain \f1\i\lang1033\fs24 o Jhesus, nach diner gr\u246 \'f6sen barmherczikait vnd gu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 ttikaitt erb\u228 \'e4rm dich v\u180 \'b4ber mich, o aller miltester Jhesus, ich bitt dich durch dinn cosper blu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 tt ...\plain \f1\lang1033\fs24 \~\endash \~... \plain \f1\i\lang1033\fs24 vnd bitt sy, dz sy im es vf seczin von dinen wegen, vnd kn\u250 \'faw den f\u250 \'far dinem gott vnd bett \plain \f1\lang1033\fs24 [20\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ]\plain \f1\i\lang1033\fs24  in an mitt herczen vnd begird vnd ergib dich im zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  ainem ewigen\plain \f1\lang1033\fs24  [!] \plain \f1\i\lang1033\fs24 vnd bitt in inenclicken vnd herczlichen, dz er sich ewenclick nitt von dir schaid mitt sinen go\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 ttlichen gn\u228 \'e4den. Amen\plain \f1\lang1033\fs24 .  Ed. einer anderen dt. Fassung (mit dem lat. Text): Kurt \plain \f1\scaps\lang1033\fs24 Ruh\plain \f1\lang1033\fs24  zusammen mit Dagmar \plain \f1\scaps\lang1033\fs24 Ladisch-Grube\plain \f1\lang1033\fs24  und Josef \plain \f1\scaps\lang1033\fs24 Brecht\plain \f1\lang1033\fs24 , Franziskanisches Schrifttum im deutschen Mittelalter, Bd. II: Texte (MTU 86), M\u252 \'fcnchen 1985, S. 345\endash 347. Lat. Text unter den Werken Anselms: PL 158, 724f. Zu Editionen und lat. Vorlage vgl. \plain \f1\scaps\lang1033\fs24 Mulder\plain \f1\lang1033\fs24 , Gebeden, G8.}

