\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 155\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 159\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 Mystische Vollkommenheitslehre}}\plain \f1\caps\lang1033\fs24 .\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Der mensch, der da komen sol zu}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs32\chcbpat17 o}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  ainem folk}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [om]}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 en leben}}\plain \f1\i\lang1033\fs24 , der mu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 s go\u252 \'fcn\plain \f1\lang1033\fs24  [156r] \plain \f1\i\lang1033\fs24 durch sich selb vnd v\u180 \'b4ber sich selb in sin ainen n\u250 \'fat mitt ainem demu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 tigen ernst in dz leben vnsers herrn Jhesu Cristy, w\u246 \'f6n den so st\u228 \'e4tt der mensch in ainem demmu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 tigen ernst ...\~\endash \~... w\u246 \'f6n der mensch stu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 nd nit vf im selber, allain in got. Die halgel\plain \f1\lang1033\fs24  [lies: \plain \f1\i\lang1033\fs24 halgen\plain \f1\lang1033\fs24  'Heiligen'] \plain \f1\i\lang1033\fs24 lerent vnd bewegent die mensch zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  tugend v\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 bnent nit dur ir ainen nucz\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 sunder durch die ere gotz vnd sin gerechtkaitt\plain \f1\lang1033\fs24 .}

