\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 ({\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 2}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 va}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \u8722 -4}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 va}}\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Predigt Nr. 1}}\plain \f1\lang1033\fs24 .  {\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Confortamini in domino et in potentia }}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [Eph 6,10]}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 . Dis\u250 \'fa wort sprichit sanctus Paulus. Er sprichit: Ir sunt starc sin in gottes tugent}}\plain \f1\i\lang1033\fs24 . In disen worten manot er \u250 \'fans vier dinge: Daz erste ist, daz wir striten sun ... \u8722 - ... Nu stritent deginliche! Got wil selbe der lon sin dez stritendin menschin.\plain \f1\lang1033\fs24   Ed.: \plain \f1\scaps\lang1033\fs24 Schiewer/Seidel\plain \f1\lang1033\fs24 , S. 1\u8722 -5, Nr. 1; \plain \f1\scaps\lang1033\fs24 Rieder\plain \f1\lang1033\fs24 , S. 92\u8722 -96, Nr. 36; \plain \f1\scaps\lang1033\fs24 Kern\plain \f1\lang1033\fs24 , S. 636\u8722 -642, Nr. 47.}

