\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 ({\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 4}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 va}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \u8722 -7}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 va}}\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930gi/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Predigt Nr. 2}}\plain \f1\lang1033\fs24 .  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Et vos similes hominibus expectantibus dominum suum, quando revertat a nuptiis }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [Lc 12,36]}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 . Dis\u250 \'fa wort sprichit \u250 \'fansir herre ze sinen iungirn vnd zaime ielichin gaistlichin menschin}}\plain \f1\i\lang1033\fs24  ... Der br\u250 \'fategon daz ist \u250 \'fansir herre got, d\u250 \'fa br\u250 \'fat daz ist d\u250 \'fa menschait ... \u8722 - ... wolti abir got, daz si \plain \f1\lang1033\fs24 [lies: \plain \f1\i\lang1033\fs24 er\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 sturbe, so wolt er gerne sterbin, daz er zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  der himilschun vro\plain \f1\i\super\lang1033\fs24 v\plain \f1\i\lang1033\fs24 de k\u230 \'e6me. \plain \f1\lang1033\fs24   Ed.: \plain \f1\scaps\lang1033\fs24 Schiewer/Seidel\plain \f1\lang1033\fs24 , S. 5\u8722 -12, Nr. 2; \plain \f1\scaps\lang1033\fs24 Rieder\plain \f1\lang1033\fs24 , S. 96\u8722 -102, Nr. 37; \plain \f1\scaps\lang1033\fs24 Kern\plain \f1\lang1033\fs24 , S. 182\u8722 -189, Nr. 1.}

