\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 ({\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 15}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 rb}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \u8722 -19}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 va}}\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Predigt Nr. 5}}\plain \f1\lang1033\fs24 .  \plain \f1\i\lang1033\fs24 Elegit eam deus et preelegit eam et in tabernaculo suo habitare eam facit\plain \f1\lang1033\fs24  [{\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 CAO 8046}}\plain \f1\lang1033\fs24 ]. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Dis\u250 \'fa wort sint gesprochin z\u226 \'e2ime iegelichin s\u230 \'e6ligin menschin}}\plain \f1\i\lang1033\fs24 . Dr\u250 \'fa dinch sint dran ze merchinne. Daz erste: Du bist irwelt. Daz andir: du bist f\u250 \'far irwelt ... \u8722 - ... Nu han ich den umbeuangin mit minen armen, den ich uerre gru\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 zte mit dem munde, und ich bin gar durheflozzin und beso\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 phte in der gotlichun su\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 zekait.\plain \f1\lang1033\fs24   Ed.: \plain \f1\scaps\lang1033\fs24 Schiewer/Seidel\plain \f1\lang1033\fs24 , S. 29\u8722 -38, Nr. 5; \plain \f1\scaps\lang1033\fs24 Rieder\plain \f1\lang1033\fs24 , S. 119\u8722 -127, Nr. 40; \plain \f1\scaps\lang1033\fs24 Kern\plain \f1\lang1033\fs24 , S. 210\u8722 -223, Nr. 4f.; \plain \f1\scaps\lang1033\fs24 Wackernagel\plain \f1\lang1033\fs24  1876, S. 531\u8722 -539 (nach dieser Hs.).}

