\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 ({\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 19}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 va}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \u8722 -23}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 rb}}\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Predigt Nr. 6}}\plain \f1\lang1033\fs24 .  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Scio hominem in Cristo ante annos etc }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [II Cor 12,2]}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 . Disiu wort sprach sant Paulus unde k\u250 \'fandit \u250 \'fans ain tail hie der gnadon}}\plain \f1\i\lang1033\fs24 , die im \u250 \'fansir herre irzaigot, do er bekert wart und er uffen dem wege nidir viel ... \u8722 - ... Wan hetti ain mentsche alle tuginde ane die minne alde alle minne ane die tuginde, des enpfienge er niemer lon. Unde darumbe suln wir crefteliche kerin an die min\plain \f1\lang1033\fs24 [23\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ]\plain \f1\i\lang1033\fs24 ne, so wirt ell\u250 \'fa \u250 \'fansir arbait ain lon uon der minne, ane die enmac niht gu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 tis gesin. \plain \f1\lang1033\fs24  Ed.: \plain \f1\scaps\lang1033\fs24 Schiewer/Seidel\plain \f1\lang1033\fs24 , S. 38\u8722 -46, Nr. 6; \plain \f1\scaps\lang1033\fs24 Rieder\plain \f1\lang1033\fs24 , S. 128\u8722 -134, Nr. 41; \plain \f1\scaps\lang1033\fs24 Kern\plain \f1\lang1033\fs24 , S. 223\u8722 -232, Nr. 5.}

