\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 ({\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 30}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 va}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \u8722 -31}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 vb}}\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Predigt Nr. 13}}\plain \f1\lang1033\fs24 .  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Transite ad me omnes, qui concupiscitis me et a generationibus meis implemini }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [Sir 24,26]}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 . Dis\u250 \'fa wort sprichit d\u250 \'fa erenriche Maria}}\plain \f1\i\lang1033\fs24 . Alle die min gerne sint, die sun ze min\plain \f1\lang1033\fs24  [lies: \plain \f1\i\lang1033\fs24 mir\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 komin, ich wil siu erv\u250 \'fallin mit minir geburte. Mit disen wortin ladit \u250 \'fans d\u250 \'fa werd\u250 \'fa frowe Maria gotis mu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 tir. Nu sulnt ir merkin, wen sie ladit ... \u8722 - ... Denne wil er \u250 \'fans durhvliezin mit sinir gothait vnd mit sinir mentschait, dc wir reht v\u180 \'b4birul\u250 \'fazic werdin der oberostun selkait. \plain \f1\lang1033\fs24  Ed.: \plain \f1\scaps\lang1033\fs24 Schiewer/Seidel\plain \f1\lang1033\fs24 , S. 63\u8722 -66, Nr. 13; \plain \f1\scaps\lang1033\fs24 Rieder\plain \f1\lang1033\fs24 , S. 153\u8722 -155, Nr. 48; \plain \f1\scaps\lang1033\fs24 Kern\plain \f1\lang1033\fs24 ., S. 239\u8722 -242, Nr. 7.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

