\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 ({\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 45}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 va}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \u8722 -53}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 rb}}\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Predigt Nr. 17}}\plain \f1\lang1033\fs24 .  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Iustum deduxit dominus per vias rectas et ostendit illi regnum dei et cetera }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [Sap 10,10]}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 . Disiv wort lisit man in den buochin der wishait, dc sprichit der hailic gaist}}\plain \f1\i\lang1033\fs24 : \u218 \'dansir herre laitit den rehtin mentschin durh den rehtin wec und o\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 git im gotis riche. In den wortin sunt ir merkin vier dinc: Daz erste ist, wer der laiter ist ... \u8722 - ... Dc ist diu zerunge, die der mentsche denne sol saminon in disim libe, dc er zerunge habe ze himilriche.\plain \f1\lang1033\fs24   Ed.: \plain \f1\scaps\lang1033\fs24 Schiewer/Seidel\plain \f1\lang1033\fs24 , S. 94\u8722 -109, Nr. 17; \plain \f1\scaps\lang1033\fs24 Rieder\plain \f1\lang1033\fs24 , S. 186\u8722 -200, Nr. 52; \plain \f1\scaps\lang1033\fs24 Kern\plain \f1\lang1033\fs24 , S. 278\u8722 -298, Nr. 11.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

