\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 ({\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 53}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 rb}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \u8722 -57}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 ra}}\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Predigt Nr. 18}}\plain \f1\lang1033\fs24 .  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Hec est voluntas dei sanctificatio vestra }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [I Th 4,3]}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 . Disiv wort sprichit sant Paulus}}\plain \f1\i\lang1033\fs24 . Gotis wille ist ivwir hailkait. Dc gotis wille sie, dc wir hailic sien, dc merkint an drin dingin: Dc erste ist, dc er \u250 \'fans geb\u250 \'fatit, dc wir hailic sien ... \u8722 - ... und in dirre bescho\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 wede solt du got lobon an allir creature und solt got irkennin an allen dingin.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Ed.: \plain \f1\scaps\lang1033\fs24 Schiewer/Seidel\plain \f1\lang1033\fs24 , S. 109\u8722 -117, Nr. 18; \plain \f1\scaps\lang1033\fs24 Rieder\plain \f1\lang1033\fs24 , S. 200\u8722 -207, Nr. 53; \plain \f1\scaps\lang1033\fs24 Kern\plain \f1\lang1033\fs24 , S. 298\u8722 -309, Nr. 12;\plain \f1\scaps\lang1033\fs24  Wackernagel\plain \f1\lang1033\fs24  1876, S. 119\u8722 -127, Nr. LIV (nach {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Z\u252 \'fcrich, Zentralbibl., Ms. C 76}}\plain \f1\lang1033\fs24 ).}

