\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 ({\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 103}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 va}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \u8722 -105}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 ra}}\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Predigt Nr. 29}}\plain \f1\lang1033\fs24 .  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ego quasi vitis fructificavi }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [Sir 24,23]}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 . Vnsir vrovwe gelichit sich an disen worten ainir rebun, vnde geschiht daz dur drie sache}}\plain \f1\i\lang1033\fs24 : Div erste sache ist, daz div rebe blu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 get. Swenn daz ist, so vluhit daz vngewrme alliz da uon ... \u8722 - ... Div dritte tugint ist, daz du an aime iegelichin werche, daz du tu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 st, daz du war n\u230 \'e6mest, waz maht du nu an disime werche getu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 n, \plain \f1\lang1033\fs24 [105\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 daz gotte allir liebist si vnde da uon unsir her an dir gelobit werde.\plain \f1\lang1033\fs24   Ed.: \plain \f1\scaps\lang1033\fs24 Schiewer/Seidel\plain \f1\lang1033\fs24 , S. 209\u8722 -212, Nr. 29; \plain \f1\scaps\lang1033\fs24 Rieder\plain \f1\lang1033\fs24 , S. 293\u8722 -296, Nr. 64; \plain \f1\scaps\lang1033\fs24 Kern\plain \f1\lang1033\fs24 , S. 400\u8722 -406, Nr. 21; \plain \f1\scaps\lang1033\fs24 Wackernagel\plain \f1\lang1033\fs24  1876, S. 106\u8722 -108, Nr. XLIX (nach {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Freiburg i.B., UB, Hs. 464}}\plain \f1\lang1033\fs24 ).}

