\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 ({\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 106}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 ra}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \u8722 -107}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 ra}}\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Predigt Nr. 32}}\plain \f1\lang1033\fs24 .  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Unsir herre sprichit in deme ewangelio ze sinen iungiron: Manete in me et ego in vobis }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [Io 15,4]}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 . Belibent in mir, so belibe ich in iv}}\plain \f1\i\lang1033\fs24 . \plain \f1\lang1033\fs24 [N]\plain \f1\i\lang1033\fs24 u sunt ir merchin, daz wir in gotte nivt mugin beliben als er in uns. Wir mugen nivt gesliefin in sine nature ... \u8722 - ... Daz ist also: Da mitte bewindit der tieuil die hant vnde griffet si an mit gaistlichir anvehtunge.\plain \f1\lang1033\fs24   Ed.: \plain \f1\scaps\lang1033\fs24 Schiewer/Seidel\plain \f1\lang1033\fs24 , S. 215\u8722 -217, Nr. 32; \plain \f1\scaps\lang1033\fs24 Rieder\plain \f1\lang1033\fs24 , S. 299\u8722 -301, Nr. 68; \plain \f1\scaps\lang1033\fs24 Kern\plain \f1\lang1033\fs24 , S. 423\u8722 -426, Nr. 27; \plain \f1\scaps\lang1033\fs24 Wackernagel\plain \f1\lang1033\fs24  1876, S. 539\u8722 -541 (nach dieser Hs.).}

