\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 e. ({\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 7}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 r}}\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 O tutrix securissima, mee mortis piissima diem horam nuncia}}\plain \f1\i\lang1033\fs24  ...\~\endash \~... patris parens et filia, nato tuo nos reconcilia. Amen\plain \f1\lang1033\fs24 .}

