\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 a. ({\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 11}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 r}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \endash 13}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 r}}\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Salve, regina misericordie, salve, mater salvatoris, vas electum, vas celestis gracie}}\plain \f1\i\lang1033\fs24  \u8230 \'85 >Vita, dulcedo.< {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Salve, verbi sacra parens, flos de spina}}\plain \f1\i\lang1033\fs24  \u8230 \'85 >Et spes nostra. Salve,< porta clausa, fons ortorum \u8230 \'85 >Ad te clamamus exules filie Eve.< {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Salve, decus virginum, mediatrix}}\plain \f1\lang1033\fs24  \u8230 \'85 (12\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 >O pia.< {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 In procinctu constituti te tuente}}\plain \f1\i\lang1033\fs24  ... et nos tue claritatis configura glorie. >O dulcis virgo Maria. Versus Ave Maria gracia. Collecta.< {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Concede, misericors deus, fragilitate }}{\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [!]}}{\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  nostre presidium}}\plain \f1\i\lang1033\fs24  ...\~\endash \~... a nostris iniquitatibus resurgamus per Cristum Dominum nostrum.\plain \f1\lang1033\fs24   Kombination von {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 AH 50, S. 318f., Nr. 245}}\plain \f1\lang1033\fs24  (Antiphona maior de B.M.V.; rubrizierte Verse: Salve, regina misericordie, vita dulcedo ... o clemens, o pia, o dulcis Maria) und {\field{\*\fldinst HYPERLINK "hida://bezlit[1].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 AH 54, S. 383\endash 385, Nr. 245}}\plain \f1\lang1033\fs24  (Salve, mater salvatoris, vas electum, vas honoris ...) mit anschlie\u223 \'dfender Kollekte.}

