\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 16}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 v}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \endash 17}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 r}}\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 Anfang des Johannesevangeliums}}\plain \f1\caps\lang1033\fs24  (\plain \f1\lang1033\fs24 Io\plain \f1\caps\lang1033\fs24  1,1\plain \f1\caps\lang1033\fs24 \endash \plain \f1\caps\lang1033\fs24 14)\plain \f1\caps\lang1033\fs24 , lat\plain \f1\lang1033\fs24 .  \plain \f1\i\lang1033\fs24 >Inicium sancti ewangelii secundum Johannem.< In principio erat verbum ...\~\endash \~... Et vidimus gloriam eius gloriam quasi unigeniti a patre, plenum gracia et veritate. Deo gracias.}

