\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 17}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 v}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \endash 18}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 v}}\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 Gebetsanweisungen zur Marienmesse Rorate coeli}}\plain \f1\caps\lang1033\fs24 .\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24 >Item wer in grossen sorgen ist der sel oder de\u223 \'df libs, ere vnd gu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 tz, der lau\u223 \'df die mes\u223 \'df lesen, die also anfacht 'Rorate celi desuper' von vnser frowen Annunciacionis.< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Item wirt sie mit andacht vnd mit guoter gewyssin vnd in guotem f\u252 \'fcrsatz gesprochen vnd volbracht}}\plain \f1\i\lang1033\fs24 , got vnd Maria geweret dich nach dines herczen trost etc. Item wenn der priester kompt, daz man opfren sol, so knw\u180 \'b4 nyder vnd sprich mit grosser andacht also: Herr, ich armer s\u252 \'fcnder opfer dir vnd diner lieben mu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 ter das ampt diser hailgen mes\u223 \'df ...\~\endash \~... vnd vor der mes\u223 \'df sol  der priester sprechen knw\u180 \'b4end die antiffen 'Hec est dies.'\plain \f1\lang1033\fs24 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 19}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 r\endash v}}\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 Dreiteiliges Bussgebet}}\plain \f1\lang1033\fs24 .  Einleitung: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Welher mensch och an welcher stat oder zuo welher zyt die nach geschribnen dry warhaiten}}\plain \f1\i\lang1033\fs24  lutterlich, nit erdaucht oder lugentlich, aber warlich v\u223 \'df herczen got dem herren vff opffren oder sprechen ist, der wirt sicher, das er bestaut im staut de\u223 \'df hails vnd der gnaden vnd erlangt daz o\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 wig leben \u8230 \'85\plain \f1\lang1033\fs24  (19\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Gebet: \plain \f1\i\lang1033\fs24 >Die erst.< {\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 O herr Jhesu Criste, ich bekenn mich, das ich swarlich ges\u252 \'fcndet hon vor diner goetlichen maiestat}}\plain \f1\i\lang1033\fs24  \u8230 \'85 >Die ander.< O herr Jhesu Criste, ich hab ain gu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 ten f\u252 \'fcrsacz \u8230 \'85 >Die dritt.< O herr Jhesu Criste, ich hab ain gu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 ten willen ze bichten all min s\u252 \'fcnd \u8230 \'85\~\endash \~\u8230 \'85 >Herr, bi\u223 \'df gna\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 dig mir s\u252 \'fcnderin.<}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

