\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 b. ({\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 61}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 r\endash v}}\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 >Di\u223 \'df sind dry ru\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 ff, die sol man ainem sterbenden menschen vor lesen, die will er die vernunft hautt.< >Der i ru\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 ff.< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Herr, ich bin der arm mensch, den du geschaffen hast von diner wetterlichen gu}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs32\chcbpat17 e}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 tte vnd krafft zu}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs32\chcbpat17 o}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  dir selber}}\plain \f1\i\lang1033\fs24  ...\~\endash \~... in diner grundlosen barmherczikait\plain \f1\lang1033\fs24 .  Parallel\u252 \'fcberlieferung: {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Augsburg, UB, Cod. III. 1. 4\u176 \'b0 2}}\plain \f1\lang1033\fs24 , Bl. 87\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24 ; ebd., {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Cod. III. 1. 8\u176 \'b0 43}}\plain \f1\lang1033\fs24 ; Bl. 30\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 31\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Schneider\plain \f1\lang1033\fs24  1988, S. 250 und 604); {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Budapest, Nationalbibl., Cod. Germ. 33}}\plain \f1\lang1033\fs24 , Bl. 24\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 26\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  und 152\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Vizkelety\plain \f1\lang1033\fs24  1969, Bd. 1, S. 85); {\field{\*\fldinst HYPERLINK "hida://5007[3].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Karlsruhe, BLB, Cod. Lichtenthal 90}}\plain \f1\lang1033\fs24 , Bl. 274\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ; ebd. {\field{\*\fldinst HYPERLINK "hida://5007[4].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Cod. Lichtenthal 140}}\plain \f1\lang1033\fs24 , Bl. 18\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Heinzer\plain \f1\scaps\lang1033\fs24 /Stamm\plain \f1\lang1033\fs24  1987, S. 294f.)}

