\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 c. (143\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 144\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 >Die dry ers\u252 \'fcnffzungen.< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Herre, ich ermanen dich der bitterkait, die du hettest an dinem jungsten se\u252 \'fcnffzen vnd an dinem ellenden tode}}\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24  (144\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Herre, ich ermanen dich dines hailgen endes}}\plain \f1\i\lang1033\fs24  ... {\field{\*\fldinst HYPERLINK "hida://5650[2].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Herre, ich ermane dich diner hailgen zungen vnd dines wolredendes mundes vnd bitt dich}}\plain \f1\i\lang1033\fs24 , herre, das du mich behu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 ttest vor allen falschen zungen vnd vor allen kleffigen zungen\plain \f1\lang1033\fs24 .  Gleiches Incipit: {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Stuttgart, WLB, Cod. brev. 74}}\plain \f1\lang1033\fs24 , Bl. 136\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 .}

