\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 g. (146\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 147\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 >Ain gebett von dem tod.<\plain \f1\lang1033\fs24  [147\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ] {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 O lieber herr Jhesu Criste, du der vns erloest hast mit dinem hailgen bluot}}\plain \f1\i\lang1033\fs24 , schrib in die sel diner dienerin din f\u252 \'fcnff wunden mit dem hailgen blu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 t, uff das sie dar inne lerne lesen din lyden vnd din liebe ...\plain \f1\lang1033\fs24   Passionsgebet mit \u228 \'e4hnlichem Incipit: {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Dillingen, Fuggersches Senioratsarchiv, VN 174}}\plain \f1\lang1033\fs24 , Bl. 26\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ; {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 New Haven (Connecticut), Yale University. Beinecke Rare Book and Manuscript Library, MS 28}}\plain \f1\lang1033\fs24  (olim Z. 111.10), Bl. 125\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  (zur Hs. s.\~o. Bl. 20\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ); {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Rostock, UB, Mss. theol. 30}}\plain \f1\lang1033\fs24 , Bl. 21\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  (mnl., 3. Viertel 15. Jh.; vgl. \plain \f1\scaps\lang1033\fs24 Heydeck\plain \f1\lang1033\fs24  2001, S. 187). }

