\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 162\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Durchgestrichener {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Text \u252 \'fcber die Passion Christi}}\plain \f1\lang1033\fs24  (aus {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Johannes von Paltz}}\plain \f1\lang1033\fs24 ?): {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Vnd spricht der selb lerer: E\u223 \'df ist nichtczlich [!], das so wol erl\u252 \'fcchtet zu}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs32\chcbpat17 o}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  warer erkantnu\u223 \'dft, nit enz\u252 \'fcndet so wol zu}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs32\chcbpat17 o}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  go}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs32\chcbpat17 e}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 tlicher liebe}}\plain \f1\i\lang1033\fs24  ...\~\endash \~... Das betrachten de\u223 \'df lyden\u223 \'df Cristi machet v\u223 \'df ainem irdischen menschen ain himelschen menschen, ja der mensch der mag es nit\plain \f1\lang1033\fs24 , Text bricht am Ende der Seite fragmentarisch ab. \endash  162\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  leer.}

