\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 206\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 208\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 Ps.-Lentulus}}\plain \f1\caps\lang1033\fs24  und {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 Flavius Josephus}}\plain \f1\caps\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 \u220 \'dcber Gestalt und Person Christi}}\plain \f1\lang1033\fs24 . Beide Texte auch {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Karlsruhe, BSB, Cod. Lichtenthal 109}}\plain \f1\lang1033\fs24 , Bl. 240\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 244\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  (Benediktinerinnen von Frauenalb, um 1540; vgl. \plain \f1\scaps\lang1033\fs24 Heinzer\plain \f1\scaps\lang1033\fs24 /Stamm\plain \f1\lang1033\fs24  1987, S. 266f., mit Verweis auf diese Hs.).}

