\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 b. (207\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 208\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Bericht des Flavius Josephus \u252 \'fcber Christus}}\plain \f1\lang1033\fs24  (Antiquitates XVIII,6).  \plain \f1\i\lang1033\fs24 Von dem herrn Cristi schribt Joseph der Jud in siner kronick also: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 E\u223 \'df ist gewesen zu}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs32\chcbpat17 o}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  disen ziten Jhesus ain wyser man}}\plain \f1\i\lang1033\fs24 , ist es anders\plain \f1\lang1033\fs24  [207\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 zimlich, das man in ain man nennen sol, der was ain wircker wunderbarer werck vnd ain lerer der menschen ...\~\endash \~... vnd wert der nam vnd geschlecht der cristen, die von im also genent sind.\plain \f1\lang1033\fs24  }

