\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 208\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 210\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 Gebet zu den Gliedern Christi}}\plain \f1\caps\lang1033\fs24  ('Salve tremendum cunctis potestatibus caput'\plain \f1\caps\lang1033\fs24 , dt.\plain \f1\caps\lang1033\fs24 )\plain \f1\caps\lang1033\fs24 , mit Ablassversprechen\plain \f1\lang1033\fs24 .  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Welher mensch andechtiglichen gru}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs32\chcbpat17 e}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 sset die glider vnsers herren, der erlangt von ainem jeden gru}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs32\chcbpat17 o}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 \u223 \'df dr\u252 \'fc hundert tag abla\u223 \'df}}\plain \f1\i\lang1033\fs24 .\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Seyt gru\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 \u223 \'df\plain \f1\lang1033\fs24 [t], {\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 du hailgs houpt vnsers behalter\u223 \'df Jhesu Cristi}}\plain \f1\i\lang1033\fs24 , allen ho\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 ptern, das ist allen gewalt, zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  fo\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 rchtende, vmb vnsern willen mit dorren gekro\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 nt ... Bi\u223 \'df gru\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 \u223 \'dft, du aller h\u250 \'fabstes angesicht vnsers lieben herrn ... Seyt gru\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 \u223 \'dft, ir aller liebsten ougen vnsers lieben herrn ...\~\endash \~... vnd verlihe mir behu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 tsamkait von allen k\u252 \'fcnfftigen s\u252 \'fcnden, der du lebst ... o\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 wiglich on ende. Amen. >Deo gracias.<\plain \f1\lang1033\fs24   Zur \u220 \'dcberlieferung vgl. \plain \f1\scaps\lang1033\fs24 Kornrumpf\plain \f1\scaps\lang1033\fs24  \plain \f1\scaps\lang1033\fs24 /\plain \f1\scaps\lang1033\fs24  \plain \f1\scaps\lang1033\fs24 V\plain \f1\scaps\lang1033\fs24 \u246 \'f6\plain \f1\scaps\lang1033\fs24 lker\plain \f1\lang1033\fs24  1968, S. 265 (mehrere \u220 \'dcbersetzungen). Zur lat. Vorlage und mnl. Hss. vgl. \plain \f1\scaps\lang1033\fs24 Mulder\plain \f1\lang1033\fs24 , Gebeden, G139. \u220 \'dcbereinstimmende \u220 \'dcbersetzung des Gebets in: {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Karlsruhe, BLB, Cod. St. Peter pap. 8}}\plain \f1\lang1033\fs24 , Bl. 77\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ; {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 M\u252 \'fcnchen, UB, 8\u176 \'b0 Cod. Ms. 269}}\plain \f1\lang1033\fs24 , Bl. 63\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ; {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 ebd., 8\u176 \'b0 Cod. Ms. 278}}\plain \f1\lang1033\fs24 , Bl. 126\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 129\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 .}

