\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 214\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 216\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 Gebet zu Maria und Johannes Evangelist}}\plain \f1\caps\lang1033\fs24   ('O intemerata et in aeternum benedicta specialis et incomparabilis virgo', dt.)\plain \f1\lang1033\fs24 .  >[...] \plain \f1\i\lang1033\fs24 gemaht von vnser lieben frowen sant Jeronimus.\plain \f1\lang1033\fs24 < {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 O onzerstoerte, gebenedyte, besondere vnd onverglichende junckfrow vnd gebererin gottes, Maria, der aller angenemest tempel gottes}}\plain \f1\i\lang1033\fs24  ... o aller sa\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 ligste frow, naige din oren der miltekait zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  minem gebett vnd bi\u223 \'df ain aller milteste helfferin in allen no\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 ten vnd angsten mir armen s\u252 \'fcnderin ... vnd minen fr\u252 \'fcnden vnd minen fienden, allen lebendigen vnd allen totten, o du aller sa\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 ligster\plain \f1\lang1033\fs24  [214\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 Johannes, ain besonderer vnd gehaymer fr\u252 \'fcnd Cristi, der du von vnserm herren Jhesu Cristo bist usserwelt, ain junckfrow ... ich ru\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 ff dich an mit der mu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 ter vnsers behalter\u223 \'df, das du mit ir din hilff mir wo\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 llest verlyhen ...\~\endash \~... der da ist mit dem vatter vnd dem sun eben wesenlich vnd mit o\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 wig, der in inen vnd mit inen lebt got durch alle welt der welten. Amen\plain \f1\lang1033\fs24 .  Edition des lat. Texts zusammen mit einer anderen dt. \u220 \'dcbersetzung: \plain \f1\scaps\lang1033\fs24 Klapper\plain \f1\lang1033\fs24  1935, S. 154\endash 158, Nr. 19. Hss. mit verschiedenen dt. \u220 \'dcbersetzungen (keine mit St. Georgen 95 \u252 \'fcbereinstimmend): {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Augsburg, UB, Cod. I. 3. 8\u176 \'b0 2}}\plain \f1\lang1033\fs24 , Bl. 222\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ; ebd., {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Cod. III. 1. 4\u176 \'b0 38}}\plain \f1\lang1033\fs24 , Bl. 113\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ; ebd., {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Cod. III.1. 8\u176 \'b0 31}}\plain \f1\lang1033\fs24 , Bl. 40\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Schneider\plain \f1\lang1033\fs24  1988, S. 522); {\field{\*\fldinst HYPERLINK "hida://5007[3].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Karlsruhe, BLB, Cod. Lichtenthal 87}}\plain \f1\lang1033\fs24 , Bl. 220\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ; ebd., {\field{\*\fldinst HYPERLINK "hida://5007[4].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Cod. Wonnenthal 14}}\plain \f1\lang1033\fs24 , Bl. 77\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Schlechter/Stamm\plain \f1\lang1033\fs24  2000, S. 367); {\field{\*\fldinst HYPERLINK "hida://5007[5].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Leipzig, UB, Rep. II. 156}}\plain \f1\lang1033\fs24 , Bl. 42\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Pensel/Stahl\plain \f1\lang1033\fs24  1998, S. 350); {\field{\*\fldinst HYPERLINK "hida://5007[6].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 M\u252 \'fcnchen, BSB, Cgm 4595}}\plain \f1\lang1033\fs24 , Bl. 189\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ; ebd.  {\field{\*\fldinst HYPERLINK "hida://5007[7].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Cgm 4701}}\plain \f1\lang1033\fs24 , Bl. 136\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Schneider\plain \f1\lang1033\fs24  1996, S. 232 und 367). \endash  Zu Lit., mnl. \u220 \'dcberlieferung und lat. Vorlage vgl. \plain \f1\scaps\lang1033\fs24 Mulder\plain \f1\lang1033\fs24 , Gebeden, G7.}

