\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 249\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 253\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f2\caps\lang1033\fs24\chcbpat17 Gebete w\u228 \'e4hrend der Messe}}\plain \f2\caps\lang1033\fs24 , mit Berufung auf {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f2\caps\lang1033\fs24\chcbpat17 Jean Gerson}}\plain \f1\lang1033\fs24 .  \plain \f1\i\lang1033\fs24 >Item so ain mensch by der mes\u223 \'df sta\plain \f1\i\super\lang1033\fs24 u\plain \f1\i\lang1033\fs24 t, sol er och opfferen< ain zytt ain gaistlich opffer. Der er aber das zyttlich nit opfferen, sol er opfferen daz gaistlich, vnd sol also zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  gott reden im herczen oder ouch mit den wortten vnd vor ab an allen hailigen tagen, setzet magister Johannes Gerson in tractatu\plain \f1\lang1033\fs24  [250\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 de immitacione ... Domine, omnia tua sunt. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Herr, gott almechtiger, alle ding, die ich besycz vnd bruch, gaistlich vnd zyttlich, sind alle din}}\plain \f1\i\lang1033\fs24 , dar vmb beger ich mich selbs dir zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  geben ain willigs opffer\~... \endash  >Dar nach sol man in sonderhait o\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 ttwa\u223 \'df opffern von denn herr<\plain \f1\lang1033\fs24  [250\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 nach geschriben dingen. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Herr gott, ich opffer dir alle mine s\u252 \'fcnd}}\plain \f1\i\lang1033\fs24  vnd mysseta\plain \f1\i\super\lang1033\fs24 u\plain \f1\i\lang1033\fs24 t\~... \endash \plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Herr, o\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 wiger gott, {\field{\*\fldinst HYPERLINK "hida://5650[2].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 ich opffer dir ouch alles, was}}\plain \f1\i\lang1033\fs24  ich gu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 tz honn gethonn\~... \endash  \plain \f1\lang1033\fs24 (251\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[3].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ich opffer dir, aller liebster herr,}}\plain \f1\i\lang1033\fs24  min junckfro\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 wlichait oder k\u252 \'fc\u223 \'dfhait, die ich willen hab zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  behalten alle myn tag\~...\plain \f1\lang1033\fs24  \endash  (251\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[4].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ich oppffer ouch dir}}\plain \f1\i\lang1033\fs24 , o\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 wiger gott, alle begu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 rd vnd notturfft sell vnd libs mines watter, miner mu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 tter\~... \endash  {\field{\*\fldinst HYPERLINK "hida://5650[5].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Herr gott, himelscher watter, ich oppffer dir ouch die begird}}\plain \f1\lang1033\fs24  [252\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 vnd notturfft aller der menschen, die mir gu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 cz gethonn habent\~... \endash \plain \f1\lang1033\fs24  (252\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[6].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ich oppffer dir ouch disse hailige me\u223 \'df}}\plain \f1\i\lang1033\fs24 , ob ich o\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 ttwa\u223 \'df u\u223 \'df diner gena\plain \f1\i\super\lang1033\fs24 u\plain \f1\i\lang1033\fs24 d dar inn verdienet hab fur die sel .N. oder fur alle glo\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 bige\plain \f1\lang1033\fs24  [252\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 selen\~...\plain \f1\lang1033\fs24  \endash  (252\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Herr o\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 wiger gott, {\field{\*\fldinst HYPERLINK "hida://5650[7].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 ich opffer dir alles iebel, was mir ie gethonn haben alle menschen}}\plain \f1\i\lang1033\fs24  ... \endash \plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[8].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ich oppffer dir, herr Jhesu Criste, och alles lyden, das mir kummen ist von den menschen}}\plain \f1\i\lang1033\fs24 , die mich betru\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 bt habent ...\~\endash \~... Das oppffer ich dir hu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 ett, herr, in din hailige f\u252 \'fcnff wunden in diser hailige me\u223 \'df. Amen\plain \f1\lang1033\fs24 .}

