\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 a. (310\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 311\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Einleitung. \plain \f1\i\lang1033\fs24 Sanctus Bonaventura in tractatu de exitu anime a corpore migratam spricht: {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Wo}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs32\chcbpat17 e}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 lcher mensch di\u223 \'df nach geschriben bettlin bettet ainem menschen, der da sterben will in achtagen dar vor oder ain oder zwenn}}\plain \f1\i\lang1033\fs24  ..., der erlediget den selben sterbenden menschen von der anfechtung de\u223 \'df bo\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 \u223 \'dfen finds ...\~\endash \~... gelob mir, got naiget sich zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  dir mit sinen gna\plain \f1\i\super\lang1033\fs24 u\plain \f1\i\lang1033\fs24 den vnd laust dich nit \u252 \'fcbel sterben.\plain \f1\lang1033\fs24  
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 b. (311\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 314\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Gebete. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Jhesu, domine deus noster, adiutor esto famule tue et lumen sancte fidei illi infunde}}\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24  (312\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Maria, virgo dulcissima mater, exultet ancilla tua in tua misericordia}}\plain \f1\lang1033\fs24  ... (312\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[3].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Jhesu, domine deus noster, secundum misericordiam tuam iudica ancillam tuam}}\plain \f1\lang1033\fs24  ... (313\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[4].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Maria, virgo beatissima, famule tue mi\u223 \'dferere}}\plain \f1\lang1033\fs24  ...}

