\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 314r\endash v}}\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 Lat. Gebet des Hieronymus f\u252 \'fcr die hl. Paula}}\plain \f1\lang1033\fs24 .  \plain \f1\i\lang1033\fs24 Jeronimus schribt zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  sant Paula, sy sol betten alle frytag vor ainem bild des haille cr\u252 \'fccz di\u223 \'df bett, so geb ir gott an irem end rechte r\u252 \'fcw vnd ware erkantnu\u223 \'df vor den anfechtungen der bo\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 \u223 \'dfen find. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Creator omnium creaturarum, quia tu ex [314v] natura es mi\u223 \'dfericors, permitte}}\plain \f1\i\lang1033\fs24  ...}

