\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 335}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\super\lang1033\fs32\chcbpat17 r}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \endash 338}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\super\lang1033\fs32\chcbpat17 v}}\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 Drei GebetE f\u252 \'fcr die armen Seelen}}\plain \f1\caps\lang1033\fs24 .\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24 >Di\u223 \'df nachfolget gebett sol man betten f\u252 \'fcr die selen vnd wirt gehaissen das gulden gebett etc.< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 O ain forchtsamer got vnd ain erschreckenlicher got, den die engel f\u252 \'fcrchten vnd die erczengel an betten}}\plain \f1\i\lang1033\fs24  ... so bitt ich dich ... \plain \f1\lang1033\fs24 (336r)\plain \f1\i\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Gegru}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs32\chcbpat17 e}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 \u223 \'dft seit ir all glo}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs32\chcbpat17 e}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 ubig selen, der lichnam hie vnd an anderen enden in Cristo rwo}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs32\chcbpat17 e}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 n}}\plain \f1\i\lang1033\fs24  ... \plain \f1\lang1033\fs24 (336r) {\field{\*\fldinst HYPERLINK "hida://5650[2].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 O herr vatter, gnaediger got, wann du ain troester bist}}\plain \f1\lang1033\fs24  [336v] \plain \f1\i\lang1033\fs24 aller betru\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 bten herczen vnd aller der, die yn gnaden stend, erbarm dich ...\~\endash \~... vnd glorificieren vnsern got vnd scho\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 pfer, den vatter vnd den sun vnd den hailgen gaist. Amen.\plain \f1\lang1033\fs24   Parallel\u252 \'fcberlieferung (\u252 \'fcberwiegend s\u252 \'fcdwestdt., Ende 15./Anfang 16. Jh.): {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Basel, UB, B XI 26}}\plain \f1\lang1033\fs24 , Bl. 145\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Meyer/Burckhardt\plain \f1\lang1033\fs24  1966, S. 1089\endash 1098); {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Budapest, Nationalbibl., Cod. Germ. 33}}\plain \f1\lang1033\fs24 , Bl. 232\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 235\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Vizkelety\plain \f1\lang1033\fs24  1969, Bd. 1, S. 91); {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Karlsruhe, BLB, Cod. U.H. 21}}\plain \f1\lang1033\fs24 , Bl. 145\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 146\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Schlechter/Stamm\plain \f1\lang1033\fs24  2000, S. 471); ebd., {\field{\*\fldinst HYPERLINK "hida://5007[3].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Cod. Wonnenthal 14}}\plain \f1\lang1033\fs24 , Bl. 280\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 283\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  (ebd., S. 372); ebd., {\field{\*\fldinst HYPERLINK "hida://5007[4].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Cod. Wonnenthal 16}}\plain \f1\lang1033\fs24 , Bl. 94\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 95\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  (ebd., S. 379); {\field{\*\fldinst HYPERLINK "hida://5007[5].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Stuttgart, WLB, Cod. brev. 62}}\plain \f1\lang1033\fs24 , Bl. 45\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Fiala/Irtenkauf\plain \f1\lang1033\fs24  1977, S. 82).}

