\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 339\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 362\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 Seelengebete zu 34 Miserere}}\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (339\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 340\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) Einleitung. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Sa}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs32\chcbpat17 e}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 lig ist die sele, der disz gebett mit andacht vnd mit ynniglichem herczen gesprochen wirt}}\plain \f1\i\lang1033\fs24 , wann alles gebett das man den selen tu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 t, daz ist vnserm herrn gar begirlich zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  enpfahen ...\plain \f1\lang1033\fs24  (340\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Wer dis\u223 \'df gebett, das her nach geschriben stett, ainer sel tu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 t mit andacht vnd mit ernst, als der mensch aller best mag die vier vnd drissig tage, die wirt on allen zwyfel ledig\~...\~\endash \~... vnd sol nyder knw\u180 \'b4en vnd sprechen >ain Miserere.<
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (340\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 362\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) 34 Mahnungen. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 O lieber minniglicher herr Jhesu Criste, ich bitt dich durch alle die liebe, die du allen menschen ye erzo}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs32\chcbpat17 e}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 gtest von dem tag}}\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24  (341\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 >Sprich ii Miserere.<\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[2].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ich manen dich der vnma}}{\field{\*\fldinst HYPERLINK "hida://5650[2].5666d/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs32\chcbpat17 e}}{\field{\*\fldinst HYPERLINK "hida://5650[2].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 \u223 \'dfigen lieben, die dich von dem va}}{\field{\*\fldinst HYPERLINK "hida://5650[2].5666d/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs32\chcbpat17 e}}{\field{\*\fldinst HYPERLINK "hida://5650[2].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 tterlichen herczen ab gezogen haut}}\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24  (342\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 >Sprich iii Miserere.< {\field{\*\fldinst HYPERLINK "hida://5650[3].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ich manen dich, lieber herr }}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [343r]}}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  Jhesu Criste, alles de\u223 \'df ellendes vnd aller der schmachait vnd der demu}}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666d/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs32\chcbpat17 o}}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 t}}\plain \f1\i\lang1033\fs24 , die du uff erdrich in menschlicher natur vor vns getragen hast ...\plain \f1\lang1033\fs24  (343\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 >iiii Miserere.<\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[4].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ach du ewiger trost, du gancze volkomne froeud aller begirlichait}}\plain \f1\i\lang1033\fs24 , ich manen dich h\u250 \'fat de\u223 \'df letsten aubent essen, das du hettest mit dinen lieben j\u252 \'fcngern ...\plain \f1\lang1033\fs24  (361\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 >xxxiiii Miserere.<\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[5].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ich manen dich, lieber herr Jhesu vnd minniglicher got, das du sassest by diner liebe mu}}{\field{\*\fldinst HYPERLINK "hida://5650[5].5666d/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs32\chcbpat17 o}}{\field{\*\fldinst HYPERLINK "hida://5650[5].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 ter}}\plain \f1\i\lang1033\fs24  vnd by andren dinen lieben fr\u252 \'fcnden ...\plain \f1\lang1033\fs24  (361\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Ach, lieber minniklicher herre Jhesu Criste, ich will h\u250 \'fat ain ganczen getrw\u180 \'b4en hon zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  diner grundlosen barmherczikait vnd diner grossen liebe ....\~\endash \~... vnd der sele vergebest alles, das sie ye\plain \f1\lang1033\fs24  [362\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 wider dich habent geton, als du vergabest dem schaucher an dem hailgen cr\u252 \'fccz. Amen. >Deo gracias.<
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 \u220 \'dcberlieferungsnachweise: https://handschriftencensus.de/werke/7281, mit 8 oberdt. Hss. (und einer mnl., {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Cgm 5203}}\plain \f1\lang1033\fs24 ), ohne diese Hs. Erg\u228 \'e4nzt werden k\u246 \'f6nnen folgende 6 oberdt. Hss.: {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Berlin, SBB-PK, Ms. germ. oct. 322}}\plain \f1\lang1033\fs24 , Bl. 72\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  (bair., 15./16. Jh.; vgl. \plain \f1\scaps\lang1033\fs24 Degering\plain \f1\lang1033\fs24  1925\endash 1932, Bd. 3, S. 100); ebd., {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Ms. germ. oct. 508}}\plain \f1\lang1033\fs24 , Bl. 56\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  (obd., 15. Jh.; ebd., S. 172); ebd., {\field{\*\fldinst HYPERLINK "hida://5007[3].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Ms. germ. oct. 1251}}\plain \f1\lang1033\fs24 , Bl. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 46\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  (schw\u228 \'e4b., Ende 15. Jh.; vgl. http://www.manuscripta-mediaevalia.de/dokumente/html/obj31250015,T [Anne-Beate Riecke]); {\field{\*\fldinst HYPERLINK "hida://5007[4].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Budapest, Nationalbibl., Cod. Germ. 16}}\plain \f1\lang1033\fs24 , 155\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 182\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  (bair.-\u246 \'f6sterr., 1. Viertel 16. Jh.; vgl. \plain \f1\scaps\lang1033\fs24 Vizkelety\plain \f1\lang1033\fs24  1969\endash 1973, Bd. 1, S. 36); {\field{\*\fldinst HYPERLINK "hida://5007[5].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Karlsruhe, BLB, Cod. Lichtenthal 99}}\plain \f1\lang1033\fs24 , Bl. 96\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 123\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  (S\u252 \'fcdwestdeutschland, 1469, vgl. \plain \f1\scaps\lang1033\fs24 Heinzer/Stamm\plain \f1\lang1033\fs24  1987, S. 241); ebd., {\field{\*\fldinst HYPERLINK "hida://5007[6].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Cod. Lichtenthal 104}}\plain \f1\lang1033\fs24 , Bl. 210\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 274\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  (aus einem s\u252 \'fcdwestdt. Benediktinerinnenkloster, 2. H\u228 \'e4lfte 15. Jh.; ebd., S. 252). \endash  Literatur zu der reichhaltigen niederl\u228 \'e4ndischen und niederdeutschen \u220 \'dcberlieferung des Gebetszyklus: \plain \f1\scaps\lang1033\fs24 Achten/Knaus\plain \f1\lang1033\fs24  1959, S. 34.}

