\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 (2\plain \f1\super\lang1033\fs24 ra\endash va\plain \f1\lang1033\fs24  Prolog)  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Hie fachet sich an ain hailsame n\u252 \'fctze lere vnd usslegung der hailgen lerer}}\plain \f1\i\lang1033\fs24  \u252 \'fcber die vier passion der hailgen vier ewangelisten. Vnd w\u252 \'fcrt hier inn begriffen, wie sich der mensch sol enz\u252 \'fcnden zu\plain \f1\i\super\lang1033\fs24 o \plain \f1\i\lang1033\fs24 go\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 tlicher liebe vnd andacht zu\plain \f1\i\super\lang1033\fs24 o \plain \f1\i\lang1033\fs24 sinem lyden ...\plain \f1\lang1033\fs24  (2\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Vnd hat dises bu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 chlin gemacht vnd von ma\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 ngen hailgen lerer ze samen gesamelt der wirdig anda\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 chtig vatter Ludolfus karthuser orden ...\~\endash \~... Vnd der text de\u223 \'df passion wirt bezaichnet vnd vnderstrichen mit rotten dympten. An dem end dises bu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 chli\u223 \'df, das ist zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  der letsten zyt vnd complet w\u252 \'fcrstu ain andechtige scho\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 ne materi hon von dem mitlyden der rainen onbeflecten mu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 ter Maria. Vnd facht der text also an\plain \f1\lang1033\fs24 .  Abdruck von gr\u246 \'f6\u223 \'dferen Teilen des Prologs nach dieser Hs.: \plain \f1\scaps\lang1033\fs24 Hohmann\plain \f1\lang1033\fs24  1977, S. 14, Anm. 21.}

