\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 13\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 18\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 Morgensegen}}\plain \f1\caps\lang1033\fs24 , dt.  \plain \f1\lang1033\fs24 Zu Morgensegen vgl. \plain \f1\scaps\lang1033\fs24 Holzmann\plain \f1\lang1033\fs24  2001, S. 276\endash 282. \plain \f1\caps\lang1033\fs24  
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 a. (13\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 15\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) Gereimter Segen. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Nun gesegen mich h\u250 \'fat die hailig driualtikait}}\plain \f1\i\lang1033\fs24  / uor allem\plain \f1\lang1033\fs24  [14\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 hertzlaid. + Gesegent mich h\u250 \'fat die hailgen f\u250 \'fanf wunden / vor allen bo\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 sen stunden. + Gesegen mich h\u250 \'fat daz rosvarwe\plain \f1\lang1033\fs24  [14\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 blu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 t, / daz Maria under ierem hertzen tru\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 g. + Gesegen mich h\u250 \'fat der uil hailig segen, / den got \u250 \'faber sich vnd \u250 \'faber allij\plain \f1\lang1033\fs24  [15\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 cristenhait ha\plain \f1\i\super\lang1033\fs24 u\plain \f1\i\lang1033\fs24 t geben. + Das cr\u250 \'fatz vnsers herren behu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 t vnd bewar mich uor allem \u250 \'fabel. +
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 b. (15\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 17\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ich beuilch mich in den mag}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [15}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\super\lang1033\fs32\chcbpat17 v}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 ]}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 tum vnser lieben frowen}}\plain \f1\i\lang1033\fs24 , da got selb inn beschlossen lag. + Ich beuilch mich in den frid aller engel. + Ich beuilch\plain \f1\lang1033\fs24  [16\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 mich in den frid vnd in den hailgen fronlicham ... + Der fronli\plain \f1\lang1033\fs24 [16\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ]\plain \f1\i\lang1033\fs24 cham vnsers herren sij min vmbhang fu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 r alle mine vigind sichtig vnd vnsichtig + ...\~\endash \~... si h\u250 \'fat min schirme vnd min schilte vnd min gelait zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  allen zitten in gottes namen. Amen\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 c. (17\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 18\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 + {\field{\*\fldinst HYPERLINK "hida://5650[3].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Die hand }}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [17}}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666d/?u"}{\fldrslt \plain \f1\super\lang1033\fs32\chcbpat17 v}}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 ]}}{\field{\*\fldinst HYPERLINK "hida://5650[3].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  gottes gesegen mich}}\plain \f1\i\lang1033\fs24 . + Der mund gottes versprech mich ...\~\endash \~... + Ich enpfilch mich in gottes gewalt. Amen.\plain \f1\lang1033\fs24  }

