\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 26\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 28\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 Namen Gottes und der Engel als Schutzsegen}}\plain \f1\caps\lang1033\fs24 .\plain \f1\b\lang1033\fs24   \plain \f1\i\lang1033\fs24 >Benediccio +.< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Deus, propicius esto michi}}\plain \f1\i\lang1033\fs24 , deus Abraham, Deus Isaac \u8230 \'85\~\endash \~\u8230 \'85 nos custodiant omnibus horis et momentis. Amen. >Qui nomina ista dei et angelorum super se portauerit\plain \f1\lang1033\fs24  [28\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 scripta, nullus diabolus nec malus homo, nulla malignitas ei nocere poterit, sed in perpetuum saluis\plain \f1\lang1033\fs24 \~[!] \plain \f1\i\lang1033\fs24 erit\plain \f1\lang1033\fs24 .< }

