\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 28\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 36\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 Gebet zu Christus um Schutz und Hilfe, mit Beschw\u246 \'f6rungsformeln}}\plain \f1\caps\lang1033\fs24 .\plain \f1\b\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 O domine }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [28}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\super\lang1033\fs32\chcbpat17 v}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 ]}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  Ihesu Criste, qui nos dignatus es redimere}}\plain \f1\i\lang1033\fs24  \u8230 \'85 adiuua me et libera me, et cu\plain \f1\lang1033\fs24 [29\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ]\plain \f1\i\lang1033\fs24 stodi me, defende me ...\plain \f1\lang1033\fs24  (32\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Adiuro uos, contrarii mei\plain \f1\lang1033\fs24  [32\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 cum sociis vestris omnibus, per deum uerum et sanctum et per omnes virtutes celorum ...\plain \f1\lang1033\fs24  (33\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 et per septem dormientes Maxi\plain \f1\lang1033\fs24 [33\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ]\plain \f1\i\lang1033\fs24 mianum, Malcum, Marcianum, Dyonisium, Johannem, Serapion et Constantinum, ut michi non noceant ...\~\endash \~... Et per tremendum diem iudicii uos adiuro et contestor, ut non habeatis licenciam\plain \f1\lang1033\fs24  [35\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 super me famulam dei N ... ala atta\plain \f1\lang1033\fs24  [36\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 atta. Criste, adiua me. Cristus + vincit, Cristus regnat, Cristus viuificat. + Ecce crucem domini nostri Ihesu Cristi fugite, partes aduerse, Cristus vin\plain \f1\lang1033\fs24 [36\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ]\plain \f1\i\lang1033\fs24 cit de tribu Iuda, radix Dauid. Alleluia.  \plain \f1\lang1033\fs24 Bei dem Schlusssatz handelt es sich um den sog. Bannspruch des Antonius von Padua; zu diesem vgl. LexMA 9, S. 48f.;\plain \f1\scaps\lang1033\fs24  Bozoky\plain \f1\lang1033\fs24  2003, S. 63f.}

