\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 a. (48\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 53\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Domine deus Sabaoth, deus Adonai, deus Moysi}}\plain \f1\i\lang1033\fs24  ... exaudi me peccatricem orantem\plain \f1\lang1033\fs24  [48\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 ad te. Deus, sancte pater, qui exaudisti tres pueros Sijdrac, Misac et Abdenago ... libera me famulam tuam ab omni malo, qui liberasti Danielem ... Deus, qui sedes super cherubin et seraphin ... Deus, qui posuisti uerbum tuum per spiritum sanctum in ore Moysi ... Tu deus, qui dedisti graciam tuam puero tuo Ioseph coram rege Pharaone ...\~\endash \~... libera me, domine,\plain \f1\lang1033\fs24  [53\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 ab omnibus insidiis dyaboli et a laqueis inimicorum meorum, ne me calide impediant.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 b. (53\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 57\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) >\plain \f1\i\lang1033\fs24 Oracio.< {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Deus, da michi robur }}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [53}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\super\lang1033\fs32\chcbpat17 v}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 ]}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  contra inimicos meos}}\plain \f1\i\lang1033\fs24  et corrobora cor meum in iusticia et iudicio ... Domine, contrariorum\plain \f1\lang1033\fs24  [?] \plain \f1\i\lang1033\fs24 meorum corda conuerte in bonam pacem ... Fuga, domine, omnes inimicos\plain \f1\lang1033\fs24  [55\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 meos a facie mea, ne nocere mihi ualeant ... Omnes sancti angeli et archangeli, estote mihi in auxilium ... Salua famulam tuam N, saluator mundi, qui per crucem et sanguinem tuum re\plain \f1\lang1033\fs24 [57\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ]\plain \f1\i\lang1033\fs24 demisti me, auxiliare famule tue N, te deprecor, deus meus. Amen.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 c. (57\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 60\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 >Oracio.< {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Regina celorum, sancta et gloriosa dei geni}}{\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [57}}{\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\super\lang1033\fs32\chcbpat17 v}}{\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 ]}}{\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 trix}}\plain \f1\i\lang1033\fs24 , virgo Maria, ora pro me cum omnibus sanctis tuis. Kyrieleyson ... Domine, salua fac fa\plain \f1\lang1033\fs24 [58\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ]\plain \f1\i\lang1033\fs24 mulam tuam, deus meus, sperantem in te. Muro tuo inexpugnabili circumcinge me, domine ...\~\endash \~... salua me, adiu[60\plain \f1\i\super\lang1033\fs24 v\plain \f1\i\lang1033\fs24 ]ua me, sancta trinitas, vnus deus, qui es benedictus in secula seculorum. Amen.}

