\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 78\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 81\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 Kreuzsegen}}\plain \f1\caps\lang1033\fs24 .\plain \f1\b\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Sanctifica me, domine}}\plain \f1\i\lang1033\fs24 , famulam tuam N signaculo sancte crucis, vt fiat mihi\plain \f1\lang1033\fs24  [79\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 obstaculum contra seua iacula inimicorum meorum ...\plain \f1\lang1033\fs24  [\plain \f1\scaps\lang1033\fs24 Franz\plain \f1\lang1033\fs24 , Benediktionen, II, S. 100]. \plain \f1\i\lang1033\fs24 O crux admirabilis, euacuacio uulneris\plain \f1\lang1033\fs24  ... [Cantus-DB 4014]. \plain \f1\i\lang1033\fs24 Protege, salua, benedic, sanctifica me famulam tuam N\plain \f1\lang1033\fs24  [80\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 crucis per signaculum\plain \f1\lang1033\fs24  ... [{\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 AH 50, S. 291, Nr. 223,4}}\plain \f1\lang1033\fs24 ]. \plain \f1\i\lang1033\fs24 >Oracio.< Oremus. Protege, sal\plain \f1\lang1033\fs24 [80\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ]\plain \f1\i\lang1033\fs24 ua, benedic, domine, famulam tuam N ...\~\endash \~... a cunctis hostibus et angustiis et infirmitate\plain \f1\lang1033\fs24  [81\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 anime et corporis me redde securam per Christum dominum nostrum. Amen.}

