\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 81\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 82\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 Bibelzitate (als Segensformeln?)}}\plain \f1\lang1033\fs24 .  \plain \f1\i\lang1033\fs24 Laudate dominum, omnes gentes, laudate eum, omnes populi ...\plain \f1\lang1033\fs24  [Ps 116,1\endash 2]. \plain \f1\i\lang1033\fs24 Titulus triumphalis nostri saluatoris: Ihesus Nazarenus\plain \f1\lang1033\fs24  [Io 19,19]. \plain \f1\i\lang1033\fs24 Deus homo factus est. Stetit Ihesus in medio discipulorum suorum\plain \f1\lang1033\fs24  [82\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 et dixit eis: Pax uobis, ego sum, nolite timere\plain \f1\lang1033\fs24  [Lc 24,36]. \plain \f1\i\lang1033\fs24 Ihesus autem transiens per medium illorum ibat\plain \f1\lang1033\fs24  [Lc 4,30].   Zum Vers Lc 4,30 als Schutz gegen Gefahren der Reise vgl. \plain \f1\scaps\lang1033\fs24 Bozoky\plain \f1\lang1033\fs24  2003, S. 63.}

