\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 \endash 57\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  \plain \f1\caps\lang1033\fs22 Teil 1:\plain \f1\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs22\chcbpat17 Feier des Klostereintritts}}\plain \f1\caps\lang1033\fs22  (\plain \f1\i\caps\lang1033\fs22 geburtstag\plain \f1\caps\lang1033\fs22 )\plain \f1\lang1033\fs22 .}

