\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 512a-b}}\plain \f1\lang1033\fs22  (Schaltzettel) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs22\chcbpat17 Weiteres zur Bedeutung des Ordensschleiers}}\plain \f1\lang1033\fs22 .  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Der weyl bedeytt}}\plain \f1\i\lang1033\fs22  auch ware abgestorbenhait der welt vnd dz du disen weyl fir deinen grab stain solt haben, vnder dem du verborgen solt ligen in dem ertrich der demiettigkait ...\~\endash \~... Das bedenck also bey dem weyl, wann du in auf setzst, wz dz wortt weyl auf im hab vnd sein bedeyttung.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 \par}

