\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 512c}}\plain \f1\lang1033\fs22  (Schaltzettel) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs22\chcbpat17 Quellennachweise zu den Gebeten zur Erneuerung der Profess}}\plain \f1\lang1033\fs22 .  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Es ist zu wisen, waraus die schenen gebett}}\plain \f1\i\lang1033\fs22  der ernuwerung der prophess genumen send worden, im nuwen getruckten creitzgeng piechlin, wa ich die selbe hab in vnserm hochzeit piechlin, aber im druck gar fil schener wol gemertt vnd gepessert \plain \f1\lang1033\fs22 [unterstrichen]. \endash  \plain \f1\i\lang1033\fs22 Das i gebett der ernuwerung deines gaistlichen stand, des jerlichen fest beschechen, alls er in hailigen orden ein gangen, wirtt begriffen in den zwai schenen gebeten, die da stand am 382 blatt, dz sich anhebt o Allmechtiger schepffer etc bis auf dz 385 blatt\plain \f1\lang1033\fs22  [vgl. Bl. 382\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 \endash 385\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 ]. \endash  \plain \f1\i\lang1033\fs22 Das ii schen getruckt gebet statt auch in vnserm ersten hochzeit piechlin zu hinderst wie ain sein prophess alle jar oder so offt es will gegen gott ernuwern soll, am 513 blatt facht an 'O du mein got vnd herr' bis auf dz 523\plain \f1\lang1033\fs22  [vgl. Bl. 513\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 \endash 522\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 ]. \endash  \plain \f1\i\lang1033\fs22 Aber dz schen gaistlich gemel ringlin hab wir in vnserm closter sust niedart nit, aber ich habs yetzt daraus \plain \f1\lang1033\fs22 [aus dem Druck]\plain \f1\i\lang1033\fs22  geschriben\plain \f1\lang1033\fs22  [vgl. Schaltzettel Bl. 243a\endash d]. \endash  \plain \f1\i\lang1033\fs22 Das iiii schen gebett, darein ains alle seine werck ordnen soll in dz leiden Cristi, ist die schen ordnung vnd bet\plain \f1\i\super\lang1033\fs24 9\plain \f1\lang1033\fs22  \~[?] \plain \f1\i\lang1033\fs22 im fest biechlein von Bergen am hailigen karfreitag, daraus man\plain \f1\lang1033\fs22  [durchgestr.: \plain \f1\i\lang1033\fs22 dz l\plain \f1\lang1033\fs22 ] \plain \f1\i\lang1033\fs22 genumen vnd ain schens gebett gemacht hatt vnd wo.\plain \f1\lang1033\fs22  [?] \plain \f1\i\lang1033\fs22 gepessert.\plain \f1\lang1033\fs22  
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \par}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

