\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 47\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Federproben (17. Jh.)}}\plain \f1\lang1033\fs24 : \plain \f1\i\lang1033\fs24 Herr\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Han\u223 \'df Girk\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 den ha..n\plain \f1\lang1033\fs24  (in sehr kleiner, kaum lesbarer Schrift)\plain \f1\i\lang1033\fs24 , Mein freundtlichen dienst vndt gruo\u223 \'df zu vor an euch\plain \f1\lang1033\fs24  (Briefanfang, 4mal), \plain \f1\i\lang1033\fs24 durch mich Han\u223 \'df Bliebel, Mu\u223 \'df dir ........ geben\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 Meniglichen hir\plain \f1\lang1033\fs24  [?], \plain \f1\i\lang1033\fs24 Mein freundlichen dienst vnd gruo\u223 \'df alles liebs vndt v\u252 \'fcr\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 Aller meniglichen\plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 Hiemit disem brief\plain \f1\lang1033\fs24 . }

