\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 70\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 Mariengebet}}\plain \f1\caps\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\i\caps\lang1033\fs24\chcbpat17 O domina gloriae}}\plain \f1\caps\lang1033\fs24 , dt.\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24 O domina glorie etc. O{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  du frow der guenliche, o du k\u250 \'fanginn der froelichait, o du brunn der miltikait vnd der erbarmhertzikait}}\plain \f1\i\lang1033\fs24  ..., tibi committo hodie etc., ich befilch mich dir h\u250 \'fat vnd alle tag mins lebens in din mu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 terliche miltikait ...\~\endash \~... dz ich mit hail vnd mitt gnad von diser welt mug schaiden vnd das ewig leben besitzen. Amen.\plain \f1\lang1033\fs24   Zum lat. Text, vielfach {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Bernhard von Clairvaux}}\plain \f1\lang1033\fs24  zugeschrieben, vgl. \plain \f1\scaps\lang1033\fs24 Haimerl\plain \f1\lang1033\fs24  1952, S. 75, Anm. 416 und S. 93, Anm. 557; \plain \f1\scaps\lang1033\fs24 Achten/Eizenh\plain \f1\scaps\lang1033\fs24 \u246 \'f6\plain \f1\scaps\lang1033\fs24 fer/Knaus\plain \f1\lang1033\fs24  1972, S. 62; \plain \f1\scaps\lang1033\fs24 Bushey\plain \f1\lang1033\fs24  2004, S. 365.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 70\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 75\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \plain \f1\caps\lang1033\fs24 '{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 Psalterium Mariae}}\plain \f1\caps\lang1033\fs24 ', dt.\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24 Hie nach sint aber scho\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 ne gru\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 sli von der k\u250 \'fanklichen mu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 tter Maria, irem lieben kind vnd v\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 bung ze eren. Ave porta paradysi. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Gegruesset sigistu, Maria, ain port des paradyses}}\plain \f1\i\lang1033\fs24 , du lebendiges holtz, dz ich hon verloren ... >ii.< Ave, in qua per graciam excitavit etc. Gegru\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 tzet sigistu, Maria, in der gott sinen gewalt durch die gnad erwellt h\u228 \'e4tt ...\~\endash \~... Salve, summe deus pater cum sanctorum exercitus. Gegru\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 sset sigistu, obroster su\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 sso\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 ster vatter, den da lobet ain jetlicher gaist mit den scharen aller hailgen ewenklich on end. Amen\plain \f1\lang1033\fs24 .  Der Text besteht aus 28 Strophen. \endash  Edition des lat. Textes: AH 35, S. 189\endash 199, Nr. XIII; F.J. \plain \f1\scaps\lang1033\fs24 Mone\plain \f1\lang1033\fs24 , Lateinische Hymnen des Mittelalters, 2. Bd. Marienlieder, S. 233\endash 245 (jeweils 150 vierzeilige Strophen, jedoch mit gleichem Anfang und Schluss). Zum lat. Text vgl. Karl Joseph \plain \f1\scaps\lang1033\fs24 Klinkhammer\plain \f1\lang1033\fs24 , 'Marienpsalter und Rosenkranz', in: \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24 VL 6 (1987), Sp. 42\endash 50, hier Sp. 43f. (1. Strophische Marienpsalter).  \endash  Zu dt. und nl. Fassungen vgl. \plain \f1\scaps\lang1033\fs24 Achten/Knaus\plain \f1\lang1033\fs24  1959, S. 206f.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 
