\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 \par}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 a. (122\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 123\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Einleitung}}\plain \f1\lang1033\fs24 . {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Die cron der muotter aller gnaden sol gebettet werden}}\plain \f1\i\lang1033\fs24 , wie hie nach geschriben st\u228 \'e4tt, vnd ist dis der gewar applas diser loblichen chron vnd gebets dr\u250 \'fa vnd sybenzig tusent zway hundert tusent siben hundert vnd acht vnd f\u250 \'fanftig tag appl\u228 \'e4s\u223 \'df. Die lxiii Ave Maria in die jar, die sy vff erden gelept h\u228 \'e4t, der sint lxiii gesin, vnd sol man ze v malen xii Ave Maria sprechen vnd vff ye xii Ave Maria i Pater noster ...\plain \f1\lang1033\fs24  (122\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Welicher mensch in angst oder betru\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 pt, es syg vmb lip oder vmb sel oder kainer\plain \f1\lang1033\fs24  [123\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 layg sach, die recht oder go\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 ttlich ist ... der gelob v\u180 \'b4nser lieben frowen dis nachgeschriben gebett ain jar ze sprechen ...\~\endash \~... vnd wil sin laiterin sin vss disem ellint in dz ewig leben\plain \f1\lang1033\fs24 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 b. (123\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 125\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Mittwoch}}\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 Item heb an an der mittwuch vnd sprich c Ave Maria, das erst f\u250 \'fanftzig sprich stend vor v\u180 \'b4nser lieben frowen bild vnd kn\u250 \'faw denn nider vnd sprich dis gebett. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ach du vffgender liechter morgenstern, der da durhl\u250 \'fachtet den himel, dz bistu, hailge junkfrow Maria}}\plain \f1\i\lang1033\fs24 , ain mu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 ter der hailgen dryfaltigkait. Ich manen dich h\u250 \'fat des ersten schreken vnd des grossen hertzlaids, dz du enpfingt von dinem lieben kind, do du inn in den tempel pra\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 cht nach der gewonhait der alten e vnd dir herr Symeon kund tett, dz din\plain \f1\lang1033\fs24  [124\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 mu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 tterlichs hertz von dins kindes marter versert vnd verwunt solt werden ...\~ Das\plain \f1\lang1033\fs24  [nachgetr.: \plain \f1\i\lang1033\fs24 ander\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 f\u250 \'fanftzig sprich kn\u250 \'fawint vor v\u180 \'b4nser frowen bild vnd sprich denn dis nachgend gebett\plain \f1\lang1033\fs24 . [124\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 Ach du getr\u250 \'fawe su\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 nerin aller s\u250 \'fander vnd du zarte gebererin Jhesu Cristi vnd du vsserwellter wolgezierter tempel der hailgen dryfaltikait, ich manen dich h\u250 \'fat des andren schreken vnd des grossen hertzlaids, dz din mu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 terlichs hertz enpfing, do du din hertz lieps aingebornes kind verloren hattest ...\~\endash \~... dz er sich ewenklich nit von mir schaide. Amen. Nun bitt, wz du wilt\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \par}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 c. (125\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 126\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Donnerstag}}\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 In dem donstag nach der conplet oder nach metti sprich 50 Ave Maria vnd sprich denn dis bett. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ach du gantze froeliche sicherliche volkomne troesterin aller r\u250 \'fawiger be}}\plain \f1\lang1033\fs24 [125\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ]\plain \f1\i\lang1033\fs24 girlicher hertzen, ich manen dich h\u250 \'fat des dritten sers vnd des vnma\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 ssigen grossen schmertzen, so din mu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 tterlichs hertz enfing, do der gemint sant Johannes zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  dir kam vnd dir seit, dz din lieps kind gefangen wz ...\~\endash \~... dz mich gehindren vnd irren muge der lieplichen angesicht din vnd dins lieben kinds\plain \f1\lang1033\fs24 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 d. (126\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 134\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Freitag}}\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 An dem frygtag vor essen sprich c Ave Maria vnd das ain f\u250 \'fanftzig sprich gend vnd kn\u250 \'faw denn nider fu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 r v\u180 \'b4nsers herren marterbild vnd sprich mit andacht dis gebett\plain \f1\lang1033\fs24 . [126\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ] {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ach du gehorsame tochter des himelschen vatters, in der gehorsame widerbracht ist}}\plain \f1\i\lang1033\fs24  die vngehorsame des ersten menschen vnd alles menschlich geschla\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 cht erkikt ist von dem ewigen tod .. ich ermanen dich h\u250 \'fat des ellenden nachfolgens, dz du ta\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 tt in mu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 tterlichen tr\u250 \'fawen vnd inn bittren schmertzen mitt dinem lieben kind ...\plain \f1\lang1033\fs24  (129\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Dz ander f\u250 \'fanftzig sprich stend vor v\u180 \'b4nsers herren marter bild vnd sprich denn dis gebet. Ach arme vngetro\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 ste ellende mu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 tter, du tro\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 sterin aller s\u250 \'fander, ich manen dich h\u250 \'fat des kla\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 glichen ston, dz du stu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 nt in bitterlichem jamer vnder dem hailgen cr\u250 \'fatz ...\plain \f1\lang1033\fs24  (131\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Das dritt f\u250 \'fanfftzig sprich vff den aubent, wenn du wilt, kn\u250 \'fawint vor v\u180 \'b4nser frowen bild vnd sprich denn dis gebett.\plain \f1\lang1033\fs24  [132\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 Ach du getr\u250 \'fawe mitlerin zw\u250 \'faschent v\u180 \'b4ns vnd dinem lieben kind, ich ermanen dich h\u250 \'fat des ellenden kla\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 glichen jamers vnd der trurigen klag, die du betru\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 pte mu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 tter hattest ob dinem totten kind, do man inn nam ab dem cr\u250 \'fatz ...\plain \f1\lang1033\fs24  (133\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Das vierd f\u250 \'fanftzig sprich nach der complet kn\u250 \'fawint vor v\u180 \'b4nser lieben frowen bild vnd sprich denn dis gebett. Ach du gnadriche milte gebererin Jhesu Cristi vnd du demu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 tige magt, ich manen dich der ellenden schaidung, so du ta\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 tt von dinem lieben kind\plain \f1\lang1033\fs24  [133\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 von dem grab mit mengem innerlichen tieffen s\u250 \'fanftzen, mit inniklichem bittrem wainen, in grosser vnma\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 ssiger krankait ...\~\endash \~...dz mich von dir vnd von dinem lieben kind geschaiden mo\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 chte. Amen\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \par}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 e. (134\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 135\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Samstag}}\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24 An dem samstag sprich f\u250 \'fanftzig Ave Maria kn\u250 \'fawint vor v\u180 \'b4nser lieben frowen bild vnd sprich denn dis gebett. {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ach du brinnender l\u250 \'fachtinder morgenstern, enz\u250 \'fandet von der minn des hailgen gaistes, vnd du vsserwellti dienerin des himelschen vatters, ich manen dich}}\plain \f1\i\lang1033\fs24  alles des laids vnd schmertzen vnd des grossen jamers vnd der inniklichen betru\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 pt vnd mu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 tterlichen ser, in dem du wa\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 rt in dem hus diner lieben schwo\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 ster, do du dins\plain \f1\lang1033\fs24  [134\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 lieben kinds gantz ber\u246 \'f6bet wa\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 rt ...\~\endash \~... dz ich in warem cristenlichen globen von hinnen schaide zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  dem gewaren himelschen vatterland. Bitt aber, wz du wilt\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \par}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 f. (135\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 137\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Sonntag.}}\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 An dem sunntag sprich f\u250 \'fanftzig Ave Maria vff blossen kn\u250 \'fawen vor v\u180 \'b4nser frowen bild vnd sprich denn dis nachgend gebett mitt grossem and\u228 \'e4cht vnd flis\u223 \'df \plain \f1\lang1033\fs24 [136r]\plain \f1\i\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ach du gewaltige gebieterin in himel vnd in ertrich vnd du gantze fro}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs32\chcbpat17 e}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 liche fro}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs32\chcbpat17 e}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 d vnd wunn aller hailgen, ich manen dich}}\plain \f1\i\lang1033\fs24  h\u250 \'fat der vnma\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 ssigen fro\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 d, die du enpfingt in der gewaren vrstende dins lieben kinds, do du gantzklich vnd gar ergetzt wurt alles des laids vnd bittren schmertzen, so du ye enpfingt ...\~\endash \~... dz ich die ewenklich werd anschowen mitt dir vnd allem himelschen here. Dz helff mir der vatter vnd der sun vnd der hailig gaist. Amen. Bitt, wz du wilt.
\par \pard\fi0\li0\tx8505\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 Abdruck nach dieser Hs.: Jakob Hubert \plain \f1\scaps\lang1033\fs24 Sch\plain \f1\scaps\lang1033\fs24 \u252 \'fc\plain \f1\scaps\lang1033\fs24 tz\plain \f1\lang1033\fs24 , Die Geschichte des Rosenkranzes unter Ber\u252 \'fccksichtigung der Rosenkranz-Geheimnisse und der Marien-Litaneien, Paderborn 1909, S. 185\endash 191. Zur \u220 \'dcberlieferung vgl. \plain \f1\scaps\lang1033\fs24 Achten/Knaus\plain \f1\lang1033\fs24  1959, S. 105, 171, 249, 261 und Register S. 382 (Morgenstern); \plain \f1\scaps\lang1033\fs24 Schneider\plain \f1\lang1033\fs24  1973, S. 229; \plain \f1\scaps\lang1033\fs24 Schneider\plain \f1\lang1033\fs24  1988, S. 567f.; \plain \f1\scaps\lang1033\fs24 Heinzer/Stamm\plain \f1\lang1033\fs24  1987, S. 242. Zu dieser Hs. (mit weiterer \u220 \'dcberlieferung und zum Inhalt) vgl. Hardo \plain \f1\scaps\lang1033\fs24 Hilg\plain \f1\lang1033\fs24 , 'Krone Unserer Lieben Frau', in: \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24 VL 5 (1985), Sp. 384\endash 392, hier Sp. 387 (B.VII.3); \plain \f1\scaps\lang1033\fs24 Hilg\plain \f1\lang1033\fs24  1981, S. 426, Nr. 64. Zu der bislang nachgewiesenen \u220 \'dcberlieferung zu erg\u228 \'e4nzen: {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Breslau, Dombibliothek, C 313}}\plain \f1\lang1033\fs24 , Bl. 253\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  (dat. 1466; vgl. http://www.manuscripta-mediaeva\-lia.de/do\-kumente/html/obj90328191,T); {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fulda, HLB, Aa 130}}\plain \f1\lang1033\fs24 , Bl. 261\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  (Boppard [?], Franzis\-kanerinnen, 2. Drittel 16. Jh.; vgl. \plain \f1\scaps\lang1033\fs24 Hausmann\plain \f1\lang1033\fs24  1992, S. 257); {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Karlsruhe, BLB, Cod. St. Georgen 95}}\plain \f1\lang1033\fs24 , Bl. 373\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 384\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  (Urspring, 1497); {\field{\*\fldinst HYPERLINK "hida://5007[3].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Stuttgart, WLB, Cod. brev. 53}}\plain \f1\lang1033\fs24 , 12\plain \f1\super\lang1033\fs32 r\plain \f1\lang1033\fs24  (Dominikanerinnen in Weiler/Esslingen, ca. 1493\endash 1496; vgl. \plain \f1\scaps\lang1033\fs24 Fiala/Irtenkauf\plain \f1\lang1033\fs24  1977, S. 73); ebd., {\field{\*\fldinst HYPERLINK "hida://5007[4].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Cod. brev. 62}}\plain \f1\lang1033\fs24 , 181\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  (ebd., 3. Drittel 15. Jh.; vgl. ebd., S. 83).}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 144\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 147\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 Lat.-dt. Gebet zu Maria um Hilfe}}\plain \f1\lang1033\fs24 .  \plain \f1\i\lang1033\fs24 So du grossi angst habist oder din fr\u250 \'fand oder so du enkains dings wellist bekumen von v\u180 \'b4nser lieben frowen sancta Maria, so kn\u250 \'faw fu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 r ir bild vnd sprich flissklich dis gebett dr\u250 \'famal, sy geweret dich sin on zwifel. Bett mit andacht\plain \f1\lang1033\fs24 . [145\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ] {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Sancta Maria, per illud gaudium, quod habuisti, quando filius tuus in virginitate natus est}}\plain \f1\i\lang1033\fs24 , adimple voluntatem meam ... >Antifona.< {\field{\*\fldinst HYPERLINK "hida://5650[1].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Angelus ad pastores ait}}\plain \f1\i\lang1033\fs24 : Annuncio vobis gaudium magnum ...\plain \f1\lang1033\fs24  [{\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 CAO 1404}}\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 >Antifona.< {\field{\*\fldinst HYPERLINK "hida://5650[2].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Angelorum regina, dei genitrix}}\plain \f1\i\lang1033\fs24 , \plain \f1\lang1033\fs24 [145\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ]\plain \f1\i\lang1033\fs24  sola virgo mater, consolare nos ...\plain \f1\lang1033\fs24  \endash  (146\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Ich su\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 ch din gnad, frow sancta Maria, dz du mir helffist vmb die sach, ich send ouch die botten zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  dir sant Michahel, sant Gabriel, sant Raphahel, minen aignen engel vnd all hailgen engel, dz du mir durch iren willen helfist vmb dis sach ... sant Katherinen vnd all hailgen ma\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 gt vnd all gottes hailgen, dz du mir durch ir wirdi helffist vmb dis sach\plain \f1\lang1033\fs24 . \endash  (147\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Peto misericordiam tuam, inicium tocius boni, virgo Maria. Ave Maria. Peto misericordiam tuam lucidam, sancta Maria ...\~\endash \~... sis pro nobis, quesumus, perpetua interventrix. Amen. Dis gebett beschl\u250 \'fass mit disen worten: Non sicut ego volo, sed sicut tu vis.}

