\uc1
\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 159\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 167\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 Gebet zu den gl\u228 \'e4ubigen Seelen und zu Maria}}\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (159\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24  Einleitung:) {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Dis nach geschriben gebett sprich ix tag vff blossen kn\u250 \'fawen}}\plain \f1\i\lang1033\fs24  vor v\u180 \'b4nser frowen bild vnd ru\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 ff ouch des ersten an alle glo\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 bigen selen, deren lip vnd gebain vnd hailtum\plain \f1\lang1033\fs24  [159\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 noch vff ertrich ru\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 wen ist vnd ir selen sint vor der beschowung gottes. Die selben selen bitt dz sy dir erwerbint mit der k\u250 \'fanklichen mu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 tter aller gnaden, dz du erfro\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 wt werdest in allen dinen angsten ...\plain \f1\lang1033\fs24  
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (159\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 165\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Gebet zu den Seelen:) {\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ich flech, ermanen v\u180 \'b4ch vnd bitt v\u180 \'b4ch, alle glo}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs32\chcbpat17 e}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 big selen durch den vater vnd durch den sun vnd den hailgen gaist}}\plain \f1\i\lang1033\fs24  ...\plain \f1\lang1033\fs24  (160\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ) \plain \f1\i\lang1033\fs24 Ich flech v\u180 \'b4ch vnd bitt v\u180 \'b4ch by Cherubin vnd Seraphin, die da alli zitt stond vor gott in dem obrosten thron ...\~\endash \~... dz ich erwerb in der k\u250 \'fanfftigen zitt mit v\u180 \'b4ch fro\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 lich vnd\plain \f1\lang1033\fs24  [165\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 sicherlich die fro\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 d der ewigen sa\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 lligkait ze niessent in jemer werinder fro\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 d vnd su\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 ssikait. Amen\plain \f1\lang1033\fs24 .
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 (165\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 167\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Gebet zu Maria:) {\field{\*\fldinst HYPERLINK "hida://5650[2].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Ich bitt dich, allergnadrichosti magt Maria, ain mu}}{\field{\*\fldinst HYPERLINK "hida://5650[2].5666d/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs32\chcbpat17 o}}{\field{\*\fldinst HYPERLINK "hida://5650[2].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 ter der erbaermd}}\plain \f1\i\lang1033\fs24 , ain mu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 tter des obrosten gottes vnd menschen, ain mu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 tter alles trostes, naigt dich gu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 ttlich ze enpfachen von mir armen s\u250 \'fander dis gebett ... Ich opffren dir dis gebett in der er des wirdigen gebets, dz du ta\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 tt, do der hailig engel sant Gabriel dir erschain ...\~\endash \~... vnd v\u180 \'b4ns mu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 tterlichen vnd erbarmhertzeklichen behu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 ttist vor gegenwu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 rtigen vnd k\u250 \'fanf\plain \f1\lang1033\fs24 [167\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ]\plain \f1\i\lang1033\fs24 tigen s\u250 \'fanden vnd vor allen frayssen lips vnd sel vnd eren. Dis bitt ich dich, o gna\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 dige, o milte, o su\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 sse magt Maria. Amen.\plain \f1\lang1033\fs24  }

