\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 172\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 Kurzes gereimtes Mariengebet}}\plain \f1\lang1033\fs24 .  \plain \f1\i\lang1033\fs24 Item wer dis nachgeschriben gebett spricht vor v\u180 \'b4nser frowen bild xxx tag nach ainandren alle tag ze xxx mal vnd zw\u250 \'faschent ainem jetlichen ge\plain \f1\lang1033\fs24 [172\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ]\plain \f1\i\lang1033\fs24 bett ain Ave Maria, der wirt von v\u180 \'b4nser lieben frowen geweret, wz muglicher bitt er von ir begert. {\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 O Maria, du vil ho}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs32\chcbpat17 e}}{\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 chster nam, / ich arme s\u250 \'fanderin ruff dich an}}\plain \f1\i\lang1033\fs24 , / ich bin ellent, ich bin arm, / ach, mu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 ter gots, dz l\u228 \'e4ss dich erbarmen / vnd hilff mir vss diser nott / durch dins lieben kindes herten grimen bittren tod Amen. Sprich Ave Maria\plain \f1\lang1033\fs24 .  Parallel\u252 \'fcberlieferung (meist mit etwas anderem Schluss): {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Budapest, Nationalbibl., Cod. Germ. 16}}\plain \f1\lang1033\fs24 , Bl. 67\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 68\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Vizekelety\plain \f1\lang1033\fs24  1969\endash 1973, Bd. 1, S. 34); {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 M\u252 \'fcnchen, BSB, Cgm 481}}\plain \f1\lang1033\fs24 , Bl. 52\plain \f1\super\lang1033\fs24 r-v\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Schneider\plain \f1\lang1033\fs24  1973, S. 417); {\field{\*\fldinst HYPERLINK "hida://5007[3].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 M\u252 \'fcnchen UB, 8\u176 \'b0 Cod. ms. 273}}\plain \f1\lang1033\fs24 , 33\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Kornrumpf\plain \f1\scaps\lang1033\fs24 /V\plain \f1\scaps\lang1033\fs24 \u246 \'f6\plain \f1\scaps\lang1033\fs24 lker\plain \f1\lang1033\fs24  1969, S. 278); {\field{\*\fldinst HYPERLINK "hida://5007[4].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Stuttgart, WLB, Cod. brev. 151}}\plain \f1\lang1033\fs24 , Bl. 292\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  (Franziskanerinnen im Bodenseegebiet, um 1600; vgl. \plain \f1\scaps\lang1033\fs24 Fiala/Irtenkauf\plain \f1\lang1033\fs24  1977, S. 185f.); {\field{\*\fldinst HYPERLINK "hida://5007[5].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Wien, \u214 \'d6NB, Cod. 3575}}\plain \f1\lang1033\fs24 , Bl. 61\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ; ebd., {\field{\*\fldinst HYPERLINK "hida://5007[6].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Cod. 4117}}\plain \f1\lang1033\fs24 , Bl. 188\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 189\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Menhardt\plain \f1\lang1033\fs24  1960\endash 1961, S. 921 und 991).}

