\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 191\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 203\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 Lat. Gebete f\u252 \'fcr die marianischen Hauptfeste}}\plain \f1\caps\lang1033\fs24  (aus {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 Nicolaus Salicetus}}\plain \f1\caps\lang1033\fs24 : '{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 Antidotarius Animae}}\plain \f1\caps\lang1033\fs24 ').
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs24 >Sequuntur oraciones quedam devote multum  ad beatissimam virginem Mariam dicende in eius sollempnitatibus aut in diebus sabbatinis et presertim in ecclesiis ipsi beatissime virgini Marie consecratis.<
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 \par}

