\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 223\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 226\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 Lat. Mariengebet}}\plain \f1\caps\lang1033\fs24  '{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 Obsecro te}}\plain \f1\caps\lang1033\fs24 '\plain \f1\lang1033\fs24 .  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Obsecro te, domina sancta Maria, mater dei, pyetate plenissima}}\plain \f1\i\lang1033\fs24 , summi regis filia, mater gloriosissima, mater orphanorum, consolacio desolarum, via errancium ...\~\endash \~... Audi et exaudi me, dulcissima Maria, mater dei et misericordie. Amen. \plain \f1\lang1033\fs24  Ed.: \plain \f1\scaps\lang1033\fs24 Leroquais\plain \f1\lang1033\fs24  1927, Bd. 2, S. 346f.; Lit.: \plain \f1\scaps\lang1033\fs24 Mulder\plain \f1\lang1033\fs24 , Gebeden, G6 (mit weiterer Ed.). }

