\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 243\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 244\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 Gebet zu den von Jesus vergossenen Blutstropfen}}\plain \f1\lang1033\fs24 .  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 O du aller liepster, o du aller su}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs32\chcbpat17 e}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 ssester, o du aller gu}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs32\chcbpat17 e}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 ttigester herr Jhesu Criste, min hertz ainigestes lieb, dir sig lob}}\plain \f1\i\lang1033\fs24 , dir sig er vnd ewige dancksagung vmb dine aller hailgesten blu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 ts tropffen, die du vergossen hast f\u250 \'far v\u180 \'b4n\u223 \'df v\u223 \'df dinem aller hailgesten lib in diner hailgen beschnidung, in diner hailgen blu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 tt schwitzung ...\~\endash \~... gib mir so\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 lliche r\u250 \'faw vnd warhaffte bu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 \u223 \'df vnd luttre bicht f\u250 \'far mine s\u250 \'fand in min hertz vnd in minen mund, als von mir begert din go\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 ttliche gerechtikait. Amen. Di\u223 \'df vorgend gebett ist von den blu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 ts tropffen v\u180 \'b4nssers herren, tu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 t als vil als c Pater noster\plain \f1\lang1033\fs24 . 
