\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 246\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 247\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 Wacholderbeertraktat}}\plain \f1\lang1033\fs24 .  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Daz ist div kraft vnd div tvgent der chranbitbere}}\plain \f1\i\lang1033\fs24 . Swer ir sib\plain \f1\lang1033\fs24 [en] \plain \f1\i\lang1033\fs24 oder nu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 n izzet niuchterlinge magen, dem kreftigentz das hirn vnd tempernt die stirn, behu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 tent daz gesiht ...\~\endash \~... Si machen den atem wol gesmach. Man sol si prechen zwischen vnser frawen gebu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 rt vnd zwischen ir scheidung oder ain wenig e. In gotes namen, amen.  \plain \f1\lang1033\fs24 Abdruck nach dieser Hs.: Sabine \plain \f1\scaps\lang1033\fs24 Kurschat-Fellinger\plain \f1\lang1033\fs24 , Kranewitt. Untersuchungen zu den altdeutschen \u220 \'dcbersetzungen des nordischen Wacholderbeertraktats (W\u252 \'fcrzburger medizinhistorische Forschungen 20), Pattensen 1983, S. 138 (Text) und 139 (Abb.). Abdruck (nur von Bl. 246\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 !): Josef \plain \f1\scaps\lang1033\fs24 Werlin\plain \f1\lang1033\fs24 , Drei deutsche Wacholder-Traktate des Sp\u228 \'e4tmittelalters, in: Sudhoffs Archiv f\u252 \'fcr Geschichte der Medizin und der Naturwissenschaften 49 (1965), S. 250\endash 254, hier S. 254. Die Hs. ist der mit Abstand \u228 \'e4lteste Textzeuge der Wacholderbeertraktat-Fassung a, die noch in drei weiteren Hss. \u252 \'fcberliefert ist: P = {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Prag, Nationalbibl., Cod. XVI.E.32}}\plain \f1\lang1033\fs24 , Bl. 38r-40r (mittelbair, Mitte/2. H\u228 \'e4lfte 15. Jh.); H\plain \f1\sub\lang1033\fs24 2\plain \f1\lang1033\fs24  = {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Heidelberg, UB, Cod. pal. germ. 558}}\plain \f1\lang1033\fs24 , Bl. 104\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  (nordbair., um 1470\endash 1485); O\plain \f1\sub\lang1033\fs24 2\plain \f1\lang1033\fs24  = {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Budapest, Sz\u233 \'e9ch\u233 \'e9nyi-Nationalbibl., Cod. germ. 52}}\plain \f1\lang1033\fs24 , Bl. 126\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 127\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  (\u246 \'f6sterreich., 1489\endash 1491) (zur \u220 \'dcbersetzung vgl. \plain \f1\scaps\lang1033\fs24 Kurschat-Fellinger\plain \f1\lang1033\fs24 , S. 77f., zu den Hss., jeweils mit Abdr. und Abb., ebd., S. 138\endash 148). }

