\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 83\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 87\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 \u220 \'dcber wahre Reue und Bu\u223 \'dfe}}\plain \f1\lang1033\fs24 .  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Eyn frey consciencie, wer die sey, daz merke}}\plain \f1\i\lang1033\fs24 . Waz maht die? Daz spricht man ge\plain \f1\lang1033\fs24 [84\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ]\plain \f1\i\lang1033\fs24 meinlich ware rewe, daz man sich vbel gehabe, neyne, vnd daz man sere weyne, neyne ...\~\endash \~... Wenn ez vnser herre gesprochen hat, wenn dez pist du schuldig, so gelaube auch, daz daz vnser herre sprach: Su\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 ne, wisse, dir sint vergeben dein su\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 nde, daz solt du wi\u223 \'dfen vnd nicht alleine glauben. >Amen.<}

