\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 87\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 \endash 92\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs22\chcbpat17 Gebete}}\plain \f1\caps\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\caps\lang1033\fs22\chcbpat17 zu den Sieben Blutvergie\u223 \'dfungen}}\plain \f1\caps\lang1033\fs22  (\plain \f1\i\caps\lang1033\fs22 vssflysse\plain \f1\caps\lang1033\fs22 ) Christi, auf die Wochentage verteilt.\plain \f1\lang1033\fs22   \plain \f1\i\lang1033\fs22 Von den siben vssflyssen. >Dominica.<\plain \f1\lang1033\fs22  [88\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 ] {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O herr Jhesu Criste, ich ermanen dich dins}}\plain \f1\i\lang1033\fs22  go\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs22 ttlichen minsamen bl\u252 \'fcienden vsfluss, der von dinem hailgen lib fliessen was, zarter herr, in diner kinthait in diner hailgen beschnidung ...\~\endash \~... dz du vns gebest so fyl gietigkait vnd semfftmietigkait, dz dir, herr, gebiesst werd f\u252 \'fcr lebidig vnd tod. Amen.\plain \f1\lang1033\fs22   Beschneidung, \u214 \'d6lberg, Gei\u223 \'dflung, Dornenkr\u246 \'f6nung, Wundmale an den H\u228 \'e4nden, Wundmale an den F\u252 \'fc\u223 \'dfen, Seitenwunde. \endash  Lit. zu den {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6922/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 sieben Blutvergie\u223 \'dfungen}}\plain \f1\lang1033\fs22 : \plain \f1\scaps\lang1033\fs22 Meertens\plain \f1\lang1033\fs22  1930-1934, Bd. 2, S. 40\endash 42; \plain \f1\scaps\lang1033\fs22 Achten/Knaus\plain \f1\lang1033\fs22  1959, S. 54 (Nr. 8, Bl. 67\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 ).
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \par}

