\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 98\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 \endash 108\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\caps\lang1033\fs22\chcbpat17 Vierzehn innere Leiden Christi am Kreuz}}\plain \f1\lang1033\fs22 .
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\i\lang1033\fs22 Dis synd xiiii inwendigen liden vnd sterben vnssers herren, die er gelidten hat am cr\u252 \'fctzs.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 O himelschlicher vater, ich din arme s\u252 \'fcnderin vnd vnwirdige creatur ermanen dich vnd dancken dir der vnvssprechlichen liebe}}\plain \f1\i\lang1033\fs22 , in der du dich naigtest von dem va\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs22 tterlichen hertzen herab in dyss ellend vnder dz rain hertzs diner wirdigen mu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs22 tter Marie ...\~\endash \~... vnd erbarm dich uber die dry stet der cristenhait, \u252 \'fcber all s\u252 \'fcnder, \u252 \'fcber alle gu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs22 tten menschen, vber all glebig selen. Amen.\plain \f1\lang1033\fs22   14 Tode Christi am Kreuz.
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \par}

