\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs22 108\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22 \endash 111\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  (Nachtrag von N1:) {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs22\chcbpat17 Gebet}}\plain \f1\caps\lang1033\fs22  des {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930gi/?u"}{\fldrslt \plain \f1\caps\lang1033\fs22\chcbpat17 hl}}\plain \f1\caps\lang1033\fs22 . {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\caps\lang1033\fs22\chcbpat17 Augustinus}}\plain \f1\lang1033\fs22 .  \plain \f1\i\lang1033\fs22 Ain gebett des hailigen Augustini, darinn sich der mensch selbs vnd all sin tain, auch die gemainen cristenhait gott vnd dem gantzen himelschen her beuilcht.\plain \f1\lang1033\fs22  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs22\chcbpat17 Herr, allmechtiger gott, welcher bist dr\u252 \'fcainig, der du bist allweg in allem vnd warest vor allem vnd wirst allweg sin ain gebenedyter gott in allem, ich beuilch dir}}\plain \f1\i\lang1033\fs22  hu\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs22 t vnd zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs22  aller zit min sel, lib, gesicht, geho\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs22 rd, versu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs22 chen, schmecken, griffen, alle mine gedenck, begirden, reden, wirckungen ...\~\endash \~... dz ich von ynen allen entphangen werd in dz ewig himmelschlich parendis, dz du vn\u223 \'df mit dinen liden vnd tod erkaufft hast, der du bist gebendyet ietz vnd zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs22  allen ewigen zitten. Amen.\plain \f1\lang1033\fs22   Andere deutsche Fassungen dieses Gebets: {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Dessau, Stadtbibliothek, Georg. 96,}}\plain \f1\lang1033\fs22  Bl. 14\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs22 \endash 15\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  (nur Anfang des Gebets, \plain \f1\scaps\lang1033\fs22 Pensel\plain \f1\lang1033\fs22  1977, S. 117f.); {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs22\chcbpat17 Stuttgart, WLB, Cod. brev. 62}}\plain \f1\lang1033\fs22 , Bl. 205\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs22  (\plain \f1\scaps\lang1033\fs22 Fiala/Irtenkauf\plain \f1\lang1033\fs22  1977, S. 83).
\par \pard\fi0\li0\qj\ri0\sb0\sa0\itap0  }

