\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 5\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 6\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 Kommuniongebet}}\plain \f1\caps\lang1033\fs24  (Sieben Mahnungen).\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24 >Ein gu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 t gebett von dem sacrament.< {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 O herr, ich uermannen dich h\u250 \'fat des enpfa}}{\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs32\chcbpat17 u}}{\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 chens, so dich din rainw mu}}{\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs32\chcbpat17 o}}{\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6922/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 tter enpfieng in der menschait vnd gothait}}\plain \f1\i\lang1033\fs24  ... O herr ich uermannen dich h\u250 \'fat des enpfa\plain \f1\i\super\lang1033\fs24 u\plain \f1\i\lang1033\fs24 chens, so du enpfangen w\u250 \'fartt von herr Symeon ... O herr ich uermannen dich des enpfa\plain \f1\i\super\lang1033\fs24 u\plain \f1\i\lang1033\fs24 chens, als du enpfangen wurd von dinen lieben jungern uff dem a\plain \f1\i\super\lang1033\fs24 u\plain \f1\i\lang1033\fs24 bbent essen ...\~\endash \~... O herr, ich uerman dich des enpfa\plain \f1\i\super\lang1033\fs24 u\plain \f1\i\lang1033\fs24 chens, so du noch in k\u250 \'fanftiger zitt wirdigklich wirst enpfangen,\plain \f1\lang1033\fs24  [6\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ] \plain \f1\i\lang1033\fs24 das du dich selber also in mir enpfauchest. Amen. Mit siben Pater noster vnd mit siben Aue Maria solt du sprechen Amen.}

