\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 6}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 v}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \endash 9}}{\field{\*\fldinst HYPERLINK "hida://4665/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 r}}\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 'Ritterschaft Jesu Christi'}}\plain \f1\caps\lang1033\fs24 .\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24 >Di\u223 \'df ist die ritterschafft Ihesu Cristy, die sol man werben die ganczen carw\u246 \'f6chen, die wart geoffnet dur insprechen des hailligen gaistes ainem sa\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 lligen karttusser in welschen landen, vnd diss ha\plain \f1\i\super\lang1033\fs24 u\plain \f1\i\lang1033\fs24 t ain cardinal besta\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 ttiget in der kanczly zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  Rom.< {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Am palmtag so fach an vnd werbe dich wider houffart in rechter diemietigkait gen got vnd allen menschen mit kn\u250 \'faen, wainen vnd anda}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs32\chcbpat17 e}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 chtigem gebett}}\plain \f1\i\lang1033\fs24  ...\~\endash \~... Am hailgen o\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 sterlichen tag so erstand mit Cristo fro\plain \f1\i\super\lang1033\fs24 u\plain \f1\i\lang1033\fs24 lich den ganczen tag vnd enfa\plain \f1\i\super\lang1033\fs24 u\plain \f1\i\lang1033\fs24 ch mit begirde vnd rechter min das hailig sacrament. Din w\u228 \'e4ffen ist der sig oder kierczen fann, da mit Cristus erstu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 nd zu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  ainem zaichen der w\u180 \'b4berw\u180 \'b4ndung diner s\u250 \'fand, als Cristus w\u180 \'b4ber wand den bittern tod\plain \f1\lang1033\fs24 .  Ed.: \plain \f1\scaps\lang1033\fs24 Breitenbach\plain \f1\lang1033\fs24  2013, S. 255-285, hier S. 278-282 (Paralleldruck dieser Hs. [K1] mit {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Frankfurt a. M., UB., Ms. Praed. 159, Bl. 149}}{\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\super\lang1033\fs32\chcbpat17 r}}{\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \endash 152}}{\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\super\lang1033\fs32\chcbpat17 v}}{\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  }}\plain \f1\lang1033\fs24 [F]). \endash  \u220 \'dcberlieferung: \plain \f1\lang1033\fs24\chcbpat8 Monika \plain \f1\scaps\lang1033\fs24\chcbpat8 Kasper-Schlottner\plain \f1\lang1033\fs24\chcbpat8 , 'Ritterschaft Jesu Christi', in: \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24\chcbpat8 VL 11 (2004), Sp. 1329\endash 1331; \plain \f1\scaps\lang1033\fs24\chcbpat8 Nemes\plain \f1\lang1033\fs24\chcbpat8  2015, S. 43, Anm. 16; \plain \f1\scaps\lang1033\fs24 Breitenbach\plain \f1\lang1033\fs24  2013, S. 265f.; https://handschriftencensus.de/werke/3069 (17 Hss., mit dieser Hs.; zu erg\u228 \'e4nzen: {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 M\u252 \'fcnchen, UB, 8\u176 \'b0 Cod. ms. 268, Bl. 130}}{\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 r}}{\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 \endash 145}}{\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 v}}{\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  }}\plain \f1\lang1033\fs24 [17. Jh.?], vgl. \plain \f1\scaps\lang1033\fs24 Breitenbach\plain \f1\lang1033\fs24 , S. 266).}

