\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 11\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 \endash 12\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 Tagzeitengebet zum Leiden Christi}}\plain \f1\caps\lang1033\fs24 .\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24 >{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Dis sind die siben zitt.}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 < }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Allu herschafft diennot, allu zu}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs32\chcbpat17 o}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 uersicht sorgot}}\plain \f1\i\lang1033\fs24  ... >Mettin zitt.< {\field{\*\fldinst HYPERLINK "hida://5650[1].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 Allu}}\plain \f1\i\lang1033\fs24  fro\plain \f1\i\super\lang1033\fs24 e\plain \f1\i\lang1033\fs24 d ward betriept, allu wishait ward uerr\u228 \'e4tten ...\~\endash \~... Aller glo\plain \f1\i\super\lang1033\fs24 u\plain \f1\i\lang1033\fs24 b ward bedakt mit ainem stain, allu miltigkait belaib allain. Nu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 n bitten wir den almechtigen got vnd sin werdige mu\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24 tter Marien, das wir alle betrachtin das liden Cristi in vnsserm herczen, das wir besiczen nach dissem leben das ewig leben. \plain \f1\lang1033\fs24  Ed.: \plain \f1\scaps\lang1033\fs24 Klapper\plain \f1\lang1033\fs24  1935, S. 362\endash 364, Nr. 103; Wolfgang \plain \f1\scaps\lang1033\fs24 Stammler\plain \f1\lang1033\fs24 , Prosa der deutschen Gotik. Eine Stilgeschichte in Texten, Berlin 1933, S. 53, Nr. 30e. Zu weiteren Editionen \plain \f1\scaps\lang1033\fs24 Schneider\plain \f1\lang1033\fs24  1973, S. 45. \endash  \u220 \'dcberlieferung (4 Hss.): \plain \f1\scaps\lang1033\fs24 Klapper\plain \f1\lang1033\fs24  1935, S. 362, Apparat. Weitere Hss.: {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Augsburg, UB, Cod. III.1.2\u176 \'b0 27, Beilage}}\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Schneider\plain \f1\lang1033\fs24  1988, S. 194); ebd.,\plain \f1\lang1033\fs20  {\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Cod. III.1.8\u186 \'ba 45, Bl. 3}}{\field{\*\fldinst HYPERLINK "hida://5007[1].501m/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 r}}\plain \f1\lang1033\fs24  (ebd., S.  616); {\field{\*\fldinst HYPERLINK "hida://5007[2].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Budapest, Ungar. Akademie der Wissenschaften, K 538, S. 81}}\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Vizkelety\plain \f1\lang1033\fs24  1969\endash 1973, II, S. 38);\plain \f1\lang1033\fs20  {\field{\*\fldinst HYPERLINK "hida://5007[3].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Esztergom, Kathedralbibl., Mss. III.171, Bl. 37}}{\field{\*\fldinst HYPERLINK "hida://5007[3].501m/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 r}}\plain \f1\lang1033\fs24  (ebd., S. 170); {\field{\*\fldinst HYPERLINK "hida://5007[4].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 M\u252 \'fcnchen, BSB, Cgm 354, Bl. 227}}{\field{\*\fldinst HYPERLINK "hida://5007[4].501m/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 r\endash v}}\plain \f1\lang1033\fs24  (\plain \f1\scaps\lang1033\fs24 Schneider\plain \f1\lang1033\fs24  1973, S. 45); ebd.\plain \f1\lang1033\fs20 , {\field{\*\fldinst HYPERLINK "hida://5007[5].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Cgm 796, Bl. }}{\field{\*\fldi