\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 13\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 Heinrich Laufenberg}}\plain \f1\caps\lang1033\fs24 : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 Lied 'Ich wais ain edlu maget fin}}\plain \f1\caps\lang1033\fs24 '\plain \f1\lang1033\fs24 .  >{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 In der wisse }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [Diu]}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  stolcze m\u250 \'fallerin.}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 <}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17   Ich wais ain edlu maget fin,}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  / }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 ain edl\u250 \'fa k\u250 \'fanigin,}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  /}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  ich wais in allen landen}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  / }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666l/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 kain stolczer\u250 \'fa kayserin}}\plain \f1\i\lang1033\fs24  ...\~\endash \~... Es wil dir spyse geben / hincz in das ewig leben, / das all din laid erga\plain \f1\i\super\lang1033\fs24 u\plain \f1\i\lang1033\fs24 t\plain \f1\lang1033\fs24 .  Parallel\u252 \'fcberlieferung:\plain \f1\lang1033\fs20  {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 olim Stra\u223 \'dfburg, Bibl. de la ville, B 121, Bl. 54}}{\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17 r}}\plain \f1\lang1033\fs24  (verbrannt). \endash  Ed.: \plain \f1\scaps\lang1033\fs24 Wackernagel\plain \f1\lang1033\fs24 , KL 1841, S. 632f., Nr. 755 (Abdruck nach der Stra\u223 \'dfburger Hs.); \plain \f1\scaps\lang1033\fs24 Wackernagel\plain \f1\lang1033\fs24 , KL 1867, S. 531f., Nr. 704 (synoptischer Abdruck der Stra\u223 \'dfburger und der Karlsruher Hs.); Max \plain \f1\scaps\lang1033\fs24 L\plain \f1\scaps\lang1033\fs24 \u252 \'fc\plain \f1\scaps\lang1033\fs24 tolf\plain \f1\lang1033\fs24  (Hg.), Geistliche Ges\u228 \'e4nge des deutschen Mittelalters. Melodien und Texte handschriftlicher \u220 \'dcberlieferung bis um 1530, Bd. 3, Kassel u.\~a. 2009, S. 70, Nr. 374 (mit Notation nach der Stra\u223 \'dfburger Hs.); \plain \f1\scaps\lang1033\fs24 Nemes\plain \f1\lang1033\fs24  2015, S. 93\endash 95 (Abdruck nach der Karlsruher Hs.). \endash  Lit.: \plain \f1\scaps\lang1033\fs24 Nemes\plain \f1\lang1033\fs24  2015, S. 45\endash 47 (zur Textgestalt der Karlsruher Hs.).}

