\pard\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 17\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 \endash 18\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\caps\lang1033\fs24\chcbpat17 Lied in der Weise des Liebe von Giengen}}\plain \f1\lang1033\fs24 .  \u220 \'dcberschrift:  \plain \f1\i\lang1033\fs24 In des Lieben wisse von Giengen. \plain \f1\lang1033\fs24 Text:\plain \f1\i\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 H\u246 \'f6ffart, ob din nit wae}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs32\chcbpat17 r}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 e, / so waiss }}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 [17}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\super\lang1033\fs32\chcbpat17 v}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 ]}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17  ich andr\u250 \'fa me}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\super\lang1033\fs32\chcbpat17 e}}{\field{\*\fldinst HYPERLINK "hida://5650[0].5666d/?u"}{\fldrslt \plain \f1\i\lang1033\fs24\chcbpat17 re, / die sind der sele gar swere}}\plain \f1\i\lang1033\fs24  ...\~\endash \~... nieman wils recht bedenken, / das er nit mag entwenken, / wie in der tod wel krencken, / es sy fru\plain \f1\i\super\lang1033\fs24 o\plain \f1\i\lang1033\fs24  oder spa\plain \f1\i\super\lang1033\fs24 u\plain \f1\i\lang1033\fs24 t.\plain \f1\lang1033\fs24   Nur hier \u252 \'fcberliefert. Ed.: Thomas \plain \f1\scaps\lang1033\fs24 Cramer\plain \f1\lang1033\fs24  (Hg.), Die kleineren Liederdichter des 14. und 15. Jahrhunderts, 4 Bde, M\u252 \'fcnchen 1977\endash 1985, Bd. 4, S. 160\endash 162 und 406. \endash  Lit.: RSM, Nr. \plain \f1\super\lang1033\fs24 1\plain \f1\lang1033\fs24 Liebe/2/1; Johannes \plain \f1\scaps\lang1033\fs24 Rettelbach\plain \f1\lang1033\fs24 , Liebe von Giengen, in: \plain \f1\super\lang1033\fs24 2\plain \f1\lang1033\fs24 VL 5 (1985), Sp. 781\endash 783.}

